// Pool-level Drizzle for the week-ahead batch — each query gets its own
// autocommit connection from the pool. One failure cannot cascade to others
// because there is no shared transaction. The explicit WHERE farm_id = $1
// in every query provides the same data isolation as RLS for this route.
const poolDb = drizzleNode(pool, { schema: dbSchema });

const router: IRouter = Router();

const XERO_ACCOUNT_MAP: Record<string, string> = {
  "seeds": "310",
  "fertiliser": "311",
  "spray": "312",
  "chemicals": "312",
  "feed": "320",
  "veterinary": "330",
  "fuel": "340",
  "machinery": "350",
  "repairs": "351",
  "rent": "360",
  "insurance": "370",
  "wages": "380",
  "utilities": "390",
  "professional-fees": "400",
  "livestock-purchase": "410",
  "livestock-sale": "200",
  "crop-sale": "210",
  "subsidy": "220",
  "general": "499",
};

function mapCategoryToXeroAccount(category: string): string {
  return XERO_ACCOUNT_MAP[category.toLowerCase()] || XERO_ACCOUNT_MAP["general"];
}

function mapVatRateToXeroTax(vatRate: string | null): string {
  if (!vatRate) return "No VAT";
  const rate = vatRate.toLowerCase();
  if (rate === "standard" || rate === "20" || rate === "20%") return "20% (VAT on Income)";
  if (rate === "reduced" || rate === "5" || rate === "5%") return "5% (VAT on Income)";
  if (rate === "zero" || rate === "0" || rate === "0%") return "Zero Rated Income";
  if (rate === "exempt") return "Exempt Income";
  return "No VAT";
}

async function validateFarmAccess(req: Request, res: Response): Promise<number | null> {
  // Short-circuit: farmRlsMiddleware already validated this farm and set the
  // RLS transaction context — skip the redundant DB round-trip.
  const cached = (req as Request & { validatedFarmId?: number }).validatedFarmId;
  if (cached) return cached;

  const farmId = parseInt(req.params.farmId as string, 10);
  if (isNaN(farmId)) {
    res.status(400).json({ error: "Invalid farm ID" });
    return null;
  }
  const [farm] = await db
    .select({ id: farmsTable.id })
    .from(farmsTable)
    .where(and(eq(farmsTable.id, farmId), eq(farmsTable.tenantId, req.tenantId!)))
    .limit(1);
  if (!farm) {
    res.status(404).json({ error: "Farm not found" });
    return null;
  }
  return farmId;
}

function getRecordId(req: Request): number | null {
  const id = parseInt(req.params.recordId as string, 10);
  return isNaN(id) ? null : id;
}

// ── Farm RLS middleware — validates farm ownership and opens a PostgreSQL
// transaction with SET LOCAL app.current_farm_id for all /farms/:farmId/* routes.
// validateFarmAccess() short-circuits on req.validatedFarmId set here.
router.use("/farms/:farmId", requireAuth, requireTenant, farmRlsMiddleware);

router.get("/farms/:farmId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const [record] = await db.select().from(farmsTable).where(eq(farmsTable.id, farmId));
  if (!record) { res.status(404).json({ error: "Farm not found" }); return; }
  res.json({ record });
});

router.put("/farms/:farmId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const {
    name, cphNumber, address, postcode, gridReference, totalAcreage, totalHectares,
    latitude, longitude, what3words,
    emergencyContactName, emergencyContactRelationship, emergencyContactPhone, emergencyContactEmail,
    sectorArable, sectorBeef, sectorSheep, sectorDairy, sectorPigs, sectorPoultry,
    sectorEggs, sectorGoats, sectorEquine, sectorHorticulture, sectorViticulture, sectorFreshProduce, sectorDeer,
    redTractorId, sbiNumber, farmManager, holdingType, assuranceBody,
    isNvzDesignated, country,
    eaml2Email, flockMark, herdMark, pigHerdMark, bcmsHoldingNumber, scotEidNumber, eidCymruNumber,
    appaRef, appaRegistrationDate, fsaWineProductionRef,
    harvestStrictStorage,
  } = req.body;

  if (!name) { res.status(400).json({ error: "Farm name is required" }); return; }

  const [updated] = await db.update(farmsTable).set({
    name,
    cphNumber: cphNumber ?? null,
    address: address ?? null,
    postcode: postcode ?? null,
    gridReference: gridReference ?? null,
    totalAcreage: totalAcreage ?? null,
    totalHectares: totalHectares ?? null,
    latitude: latitude ?? null,
    longitude: longitude ?? null,
    what3words: what3words ?? null,
    emergencyContactName: emergencyContactName ?? null,
    emergencyContactRelationship: emergencyContactRelationship ?? null,
    emergencyContactPhone: emergencyContactPhone ?? null,
    emergencyContactEmail: emergencyContactEmail ?? null,
    sectorArable: sectorArable ?? false,
    sectorBeef: sectorBeef ?? false,
    sectorSheep: sectorSheep ?? false,
    sectorDairy: sectorDairy ?? false,
    sectorPigs: sectorPigs ?? false,
    sectorPoultry: sectorPoultry ?? false,
    sectorEggs: sectorEggs ?? false,
    sectorGoats: sectorGoats ?? false,
    sectorEquine: sectorEquine ?? false,
    sectorHorticulture: sectorHorticulture ?? false,
    sectorViticulture: sectorViticulture ?? false,
    sectorFreshProduce: sectorFreshProduce ?? false,
    sectorDeer: sectorDeer ?? false,
    redTractorId: redTractorId ?? null,
    sbiNumber: sbiNumber ?? null,
    farmManager: farmManager ?? null,
    holdingType: holdingType ?? null,
    assuranceBody: assuranceBody ?? null,
    isNvzDesignated: isNvzDesignated ?? false,
    country: country ?? "england",
    eaml2Email: eaml2Email ?? null,
    flockMark: flockMark ?? null,
    herdMark: herdMark ?? null,
    pigHerdMark: pigHerdMark ?? null,
    bcmsHoldingNumber: bcmsHoldingNumber ?? null,
    scotEidNumber: scotEidNumber ?? null,
    eidCymruNumber: eidCymruNumber ?? null,
    appaRef: appaRef ?? null,
    appaRegistrationDate: appaRegistrationDate ?? null,
    fsaWineProductionRef: fsaWineProductionRef ?? null,
    harvestStrictStorage: harvestStrictStorage ?? false,
  })
  .where(and(eq(farmsTable.id, farmId), eq(farmsTable.tenantId, req.tenantId!)))
  .returning();

  if (!updated) { res.status(404).json({ error: "Farm not found" }); return; }
  res.json({ record: updated });
});

router.get("/farms/:farmId/dashboard", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const [farm] = await db.select().from(farmsTable).where(eq(farmsTable.id, farmId));

  const subs = await db
    .select({
      id: subscriptionsTable.id,
      farmId: subscriptionsTable.farmId,
      moduleId: subscriptionsTable.moduleId,
      moduleName: modulesTable.name,
      moduleKey: modulesTable.key,
      status: subscriptionsTable.status,
      currentPeriodEnd: subscriptionsTable.currentPeriodEnd,
    })
    .from(subscriptionsTable)
    .innerJoin(modulesTable, eq(subscriptionsTable.moduleId, modulesTable.id))
    .where(and(eq(subscriptionsTable.farmId, farmId), eq(subscriptionsTable.tenantId, req.tenantId!)));

  const now = new Date();
  const activeSubs = subs.filter(
    (s) =>
      s.status === "active" ||
      (s.status === "trial" && (!s.currentPeriodEnd || s.currentPeriodEnd > now)),
  );

  const [
    [inspResult],
    [ncCount],
    [overdueInspCount],
    [fieldCount],
    [equipmentCount],
    [sprayCount],
    [inspectionCount],
    overdueNcItems,
    overdueInspItems,
  ] = await Promise.all([
    db
      .select({ nextDue: inspectionRecordsTable.nextInspectionDue })
      .from(inspectionRecordsTable)
      .where(eq(inspectionRecordsTable.farmId, farmId))
      .orderBy(desc(inspectionRecordsTable.inspectionDate))
      .limit(1),
    db
      .select({ count: sql<number>`count(*)::int` })
      .from(nonconformanceRecordsTable)
      .where(and(eq(nonconformanceRecordsTable.farmId, farmId), eq(nonconformanceRecordsTable.status, "open"))),
    db
      .select({ count: sql<number>`count(*)::int` })
      .from(inspectionRecordsTable)
      .where(and(eq(inspectionRecordsTable.farmId, farmId), lt(inspectionRecordsTable.nextInspectionDue, now))),
    db
      .select({ count: sql<number>`count(*)::int` })
      .from(fieldsTable)
      .where(and(eq(fieldsTable.farmId, farmId), eq(fieldsTable.isActive, true))),
    db
      .select({ count: sql<number>`count(*)::int` })
      .from(equipmentTable)
      .where(eq(equipmentTable.farmId, farmId)),
    db
      .select({ count: sql<number>`count(*)::int` })
      .from(sprayApplicationsTable)
      .where(eq(sprayApplicationsTable.farmId, farmId)),
    db
      .select({ count: sql<number>`count(*)::int` })
      .from(inspectionRecordsTable)
      .where(eq(inspectionRecordsTable.farmId, farmId)),
    db
      .select({ id: nonconformanceRecordsTable.id, category: nonconformanceRecordsTable.category, description: nonconformanceRecordsTable.description })
      .from(nonconformanceRecordsTable)
      .where(and(eq(nonconformanceRecordsTable.farmId, farmId), eq(nonconformanceRecordsTable.status, "open")))
      .orderBy(desc(nonconformanceRecordsTable.identifiedDate))
      .limit(5),
    db
      .select({ id: inspectionRecordsTable.id, inspectionType: inspectionRecordsTable.inspectionType, nextInspectionDue: inspectionRecordsTable.nextInspectionDue })
      .from(inspectionRecordsTable)
      .where(and(eq(inspectionRecordsTable.farmId, farmId), lt(inspectionRecordsTable.nextInspectionDue, now)))
      .orderBy(asc(inspectionRecordsTable.nextInspectionDue))
      .limit(5),
  ]);

  const overdueItems: { type: "nonconformance" | "inspection"; description: string; href: string }[] = [
    ...overdueNcItems.map((nc) => ({
      type: "nonconformance" as const,
      description: `Open NC: ${nc.category}${nc.description ? ` — ${nc.description.slice(0, 60)}${nc.description.length > 60 ? "…" : ""}` : ""}`,
      href: "/inspections",
    })),
    ...overdueInspItems.map((insp) => ({
      type: "inspection" as const,
      description: `Overdue inspection: ${insp.inspectionType}`,
      href: "/inspections",
    })),
  ];

  // Calving tagging compliance: tag 1 within 36h, tag 2 within 20 days (Red Tractor Dairy / UK cattle tracing)
  const cutoff36h = new Date(now.getTime() - 36 * 60 * 60 * 1000);
  const cutoff20d = new Date(now.getTime() - 20 * 24 * 60 * 60 * 1000);
  const cutoff30d = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  const overdueTagCalvings = await db
    .select({
      calvingDate: dairyCalvingRecordsTable.calvingDate,
      cowEarTag: dairyCalvingRecordsTable.cowEarTag,
      calfEarTag: dairyCalvingRecordsTable.calfEarTag,
      calfEarTag2: dairyCalvingRecordsTable.calfEarTag2,
    })
    .from(dairyCalvingRecordsTable)
    .where(and(
      eq(dairyCalvingRecordsTable.farmId, farmId),
      eq(dairyCalvingRecordsTable.calfOutcome, "live"),
      gte(dairyCalvingRecordsTable.calvingDate, cutoff30d),
      or(
        and(isNull(dairyCalvingRecordsTable.calfEarTag), lt(dairyCalvingRecordsTable.calvingDate, cutoff36h)),
        and(isNull(dairyCalvingRecordsTable.calfEarTag2), lt(dairyCalvingRecordsTable.calvingDate, cutoff20d)),
      )
    ))
    .orderBy(desc(dairyCalvingRecordsTable.calvingDate))
    .limit(5);
  for (const c of overdueTagCalvings) {
    const dam = c.cowEarTag ? ` — dam: ${c.cowEarTag}` : "";
    if (!c.calfEarTag) {
      overdueItems.push({ type: "inspection", description: `Calf tag 1 overdue${dam} (tag within 36h of birth)`, href: "/dairy?tab=calving" });
    } else if (!c.calfEarTag2) {
      overdueItems.push({ type: "inspection", description: `Calf tag 2 overdue${dam} (second tag within 20 days)`, href: "/dairy?tab=calving" });
    }
  }

  const today = new Date().toISOString().slice(0, 10);

  const [
    [totalTasksRow],
    [completedTasksRow],
    [overdueTasksRow],
    moduleTaskRows,
  ] = await Promise.all([
    db.select({ count: sql<number>`count(*)::int` })
      .from(farmTaskAssignmentsTable)
      .where(eq(farmTaskAssignmentsTable.farmId, farmId)),
    db.select({ count: sql<number>`count(*)::int` })
      .from(farmTaskAssignmentsTable)
      .where(and(
        eq(farmTaskAssignmentsTable.farmId, farmId),
        eq(farmTaskAssignmentsTable.status, "completed"),
      )),
    db.select({ count: sql<number>`count(*)::int` })
      .from(farmTaskAssignmentsTable)
      .where(and(
        eq(farmTaskAssignmentsTable.farmId, farmId),
        eq(farmTaskAssignmentsTable.status, "pending"),
        sql`${farmTaskAssignmentsTable.dueDate} < ${today}`,
      )),
    db.select({
      module: farmTaskAssignmentsTable.module,
      total: sql<number>`count(*)::int`,
      completed: sql<number>`count(*) filter (where ${farmTaskAssignmentsTable.status} = 'completed')::int`,
      lastActivity: sql<string | null>`max(${farmTaskAssignmentsTable.completedAt})::text`,
      hasOverdue: sql<boolean>`bool_or(${farmTaskAssignmentsTable.status} = 'pending' and ${farmTaskAssignmentsTable.dueDate} < ${today})`,
    })
      .from(farmTaskAssignmentsTable)
      .where(and(
        eq(farmTaskAssignmentsTable.farmId, farmId),
        sql`${farmTaskAssignmentsTable.module} is not null`,
      ))
      .groupBy(farmTaskAssignmentsTable.module),
  ]);

  const totalForms = totalTasksRow?.count ?? 0;
  const completedForms = completedTasksRow?.count ?? 0;
  const taskOverdue = overdueTasksRow?.count ?? 0;

  const moduleTaskMap = new Map(moduleTaskRows.map((r) => [r.module, r]));

  const moduleStats = activeSubs.map((s) => {
    const taskStats = moduleTaskMap.get(s.moduleKey);
    return {
      moduleKey: s.moduleKey,
      moduleName: s.moduleName,
      recordCount: taskStats?.total ?? 0,
      completedCount: taskStats?.completed ?? 0,
      lastActivity: taskStats?.lastActivity ?? null,
      hasOverdue: taskStats?.hasOverdue ?? false,
    };
  });

  let complianceScore: number;
  if (totalForms > 0) {
    const completionRate = completedForms / totalForms;
    const overduePenalty = Math.min(taskOverdue * 4, 25);
    complianceScore = Math.max(0, Math.min(95, Math.round(completionRate * 100) - overduePenalty));
  } else {
    const ncOverdue = ncCount.count + overdueInspCount.count;
    complianceScore = ncOverdue === 0 ? 90 : Math.max(50, 90 - ncOverdue * 5);
  }

  const totalOverdue = taskOverdue + ncCount.count + overdueInspCount.count;

  res.json({
    farm,
    complianceScore,
    totalForms,
    completedForms,
    overdueActions: totalOverdue,
    overdueItems,
    upcomingInspection: inspResult?.nextDue || null,
    fieldCount: fieldCount.count,
    equipmentCount: equipmentCount.count,
    sprayCount: sprayCount.count,
    inspectionCount: inspectionCount.count,
    moduleStats,
    activeSubscriptions: (() => {
      const direct = activeSubs.map((s) => ({
        id: s.id,
        farmId: s.farmId,
        moduleId: s.moduleId,
        moduleKey: s.moduleKey,
        moduleName: s.moduleName,
        status: s.status,
        currentPeriodEnd: s.currentPeriodEnd,
        bundled: false,
      }));
      const directKeys = new Set(direct.map(s => s.moduleKey));
      const expanded = expandModuleKeys([...directKeys]);
      const bundledEntries = expanded
        .filter(k => !directKeys.has(k))
        .map(k => ({ id: 0, farmId, moduleId: 0, moduleKey: k, moduleName: k, status: "active" as const, currentPeriodEnd: null, bundled: true }));
      return [...direct, ...bundledEntries];
    })(),
  });
});

router.get("/farms/:farmId/modules", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const subs = await db
    .select({ moduleKey: modulesTable.key, status: subscriptionsTable.status, currentPeriodEnd: subscriptionsTable.currentPeriodEnd })
    .from(subscriptionsTable)
    .innerJoin(modulesTable, eq(subscriptionsTable.moduleId, modulesTable.id))
    .where(and(
      eq(subscriptionsTable.farmId, farmId),
      eq(subscriptionsTable.tenantId, req.tenantId!),
    ));
  const nowMs = Date.now();
  const activeSubs = subs.filter(
    (s) =>
      s.status === "active" ||
      (s.status === "trial" && (!s.currentPeriodEnd || new Date(s.currentPeriodEnd).getTime() > nowMs)),
  );
  res.json({ activeModuleKeys: expandModuleKeys(activeSubs.map((s) => s.moduleKey)) });
});

router.get("/farms/:farmId/activity", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const [sprays, inspections, fields, equipment, soilTests, visitors] = await Promise.all([
    db.select({ id: sprayApplicationsTable.id, createdAt: sprayApplicationsTable.applicationDate, label: sprayApplicationsTable.operatorName })
      .from(sprayApplicationsTable).where(eq(sprayApplicationsTable.farmId, farmId)).orderBy(desc(sprayApplicationsTable.applicationDate)).limit(5),
    db.select({ id: inspectionRecordsTable.id, createdAt: inspectionRecordsTable.inspectionDate, label: inspectionRecordsTable.inspectionType })
      .from(inspectionRecordsTable).where(eq(inspectionRecordsTable.farmId, farmId)).orderBy(desc(inspectionRecordsTable.inspectionDate)).limit(5),
    db.select({ id: fieldsTable.id, createdAt: fieldsTable.createdAt, label: fieldsTable.name })
      .from(fieldsTable).where(eq(fieldsTable.farmId, farmId)).orderBy(desc(fieldsTable.createdAt)).limit(5),
    db.select({ id: equipmentTable.id, createdAt: equipmentTable.createdAt, label: equipmentTable.name })
      .from(equipmentTable).where(eq(equipmentTable.farmId, farmId)).orderBy(desc(equipmentTable.createdAt)).limit(5),
    db.select({ id: soilTestRecordsTable.id, createdAt: soilTestRecordsTable.sampleDate, label: soilTestRecordsTable.sampleReference })
      .from(soilTestRecordsTable).where(eq(soilTestRecordsTable.farmId, farmId)).orderBy(desc(soilTestRecordsTable.sampleDate)).limit(5),
    db.select({ id: visitorContractorLogTable.id, createdAt: visitorContractorLogTable.arrivalTime, label: visitorContractorLogTable.visitorName })
      .from(visitorContractorLogTable).where(eq(visitorContractorLogTable.farmId, farmId)).orderBy(desc(visitorContractorLogTable.arrivalTime)).limit(5),
  ]);

  const activities = [
    ...sprays.map((r) => ({ id: `spray-${r.id}`, module: "sprays", description: `Spray application recorded${r.label ? ` by ${r.label}` : ""}`, createdAt: r.createdAt })),
    ...inspections.map((r) => ({ id: `insp-${r.id}`, module: "inspections", description: `Inspection completed${r.label ? `: ${r.label}` : ""}`, createdAt: r.createdAt })),
    ...fields.map((r) => ({ id: `field-${r.id}`, module: "fields", description: `Field registered: ${r.label ?? "Unnamed"}`, createdAt: r.createdAt })),
    ...equipment.map((r) => ({ id: `equip-${r.id}`, module: "equipment", description: `Equipment added: ${r.label ?? "Unnamed"}`, createdAt: r.createdAt })),
    ...soilTests.map((r) => ({ id: `soil-${r.id}`, module: "soil", description: `Soil test submitted${r.label ? ` (ref: ${r.label})` : ""}`, createdAt: r.createdAt })),
    ...visitors.map((r) => ({ id: `visitor-${r.id}`, module: "visitors", description: `Visitor logged: ${r.label ?? "Unknown"}`, createdAt: r.createdAt })),
  ]
    .filter((a) => a.createdAt)
    .sort((a, b) => new Date(b.createdAt!).getTime() - new Date(a.createdAt!).getTime())
    .slice(0, 10);

  res.json({ activities });
});

// ─── Fields ─────────────────────────────────────────
router.get("/farms/:farmId/fields", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const fields = await db.select().from(fieldsTable).where(eq(fieldsTable.farmId, farmId)).orderBy(desc(fieldsTable.createdAt));
  const enclosedSums = await db
    .select({ fieldId: environmentalFeaturesTable.fieldId, totalHa: sql<string>`SUM(${environmentalFeaturesTable.areaHectares})` })
    .from(environmentalFeaturesTable)
    .where(and(eq(environmentalFeaturesTable.farmId, farmId), eq(environmentalFeaturesTable.isEnclosed, true)))
    .groupBy(environmentalFeaturesTable.fieldId);
  const enclosedByField: Record<number, number> = {};
  for (const e of enclosedSums) { if (e.fieldId) enclosedByField[e.fieldId] = parseFloat(e.totalHa ?? "0"); }
  const records = fields.map(f => {
    const enclosedHa = enclosedByField[f.id] ?? 0;
    const grossHa = parseFloat(String(f.areaHectares ?? "0")) || 0;
    const computedFarmableAreaHa = f.farmableAreaHectares != null
      ? parseFloat(String(f.farmableAreaHectares))
      : Math.max(0, grossHa - enclosedHa);
    return { ...f, enclosedFeatureAreaHa: enclosedHa, computedFarmableAreaHa };
  });
  res.json({ records });
});

