router.post("/farms/:farmId/field-season-land-use", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const { fieldId, year, season, landUse, schemeActionCode, schemeReference, areaHectares, startDate, endDate, managementNotes } = req.body;
  if (!fieldId || !year || !landUse) { res.status(400).json({ error: "fieldId, year and landUse are required" }); return; }
  const [field] = await db.select({ id: fieldsTable.id }).from(fieldsTable).where(and(eq(fieldsTable.id, Number(fieldId)), eq(fieldsTable.farmId, farmId))).limit(1);
  if (!field) { res.status(400).json({ error: "Field not found on this farm" }); return; }
  const [record] = await db.insert(fieldSeasonLandUseTable).values({
    farmId, fieldId: Number(fieldId), year: Number(year), season: season || null, landUse,
    schemeActionCode: schemeActionCode || null, schemeReference: schemeReference || null,
    areaHectares: areaHectares || null, startDate: startDate || null, endDate: endDate || null,
    managementNotes: managementNotes || null,
  }).returning();
  res.status(201).json({ record });
});

router.patch("/farms/:farmId/field-season-land-use/:id", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const id = Number(req.params.id);
  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
  const [existing] = await db.select({ id: fieldSeasonLandUseTable.id }).from(fieldSeasonLandUseTable)
    .where(and(eq(fieldSeasonLandUseTable.id, id), eq(fieldSeasonLandUseTable.farmId, farmId))).limit(1);
  if (!existing) { res.status(404).json({ error: "Not found" }); return; }
  const allowed: Record<string, unknown> = {};
  const fields = ["year", "season", "landUse", "schemeActionCode", "schemeReference", "areaHectares", "startDate", "endDate", "managementNotes"];
  for (const f of fields) { if (req.body[f] !== undefined) allowed[f] = req.body[f] || null; }
  if (req.body.year !== undefined) allowed.year = Number(req.body.year);
  if (req.body.landUse) allowed.landUse = req.body.landUse;
  const [record] = await db.update(fieldSeasonLandUseTable).set(allowed).where(eq(fieldSeasonLandUseTable.id, id)).returning();
  res.json({ record });
});

router.delete("/farms/:farmId/field-season-land-use/:id", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const id = Number(req.params.id);
  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
  const [existing] = await db.select({ id: fieldSeasonLandUseTable.id }).from(fieldSeasonLandUseTable)
    .where(and(eq(fieldSeasonLandUseTable.id, id), eq(fieldSeasonLandUseTable.farmId, farmId))).limit(1);
  if (!existing) { res.status(404).json({ error: "Not found" }); return; }
  await db.delete(fieldSeasonLandUseTable).where(eq(fieldSeasonLandUseTable.id, id));
  res.json({ success: true });
});

// ─── Harvests ───────────────────────────────────────
router.get("/farms/:farmId/harvests", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const fieldId = req.query.fieldId ? Number(req.query.fieldId) : null;
  const whereClause = fieldId && !isNaN(fieldId)
    ? and(eq(fieldsTable.farmId, farmId), eq(fieldsTable.id, fieldId))
    : eq(fieldsTable.farmId, farmId);
  const records = await db
    .select()
    .from(harvestRecordsTable)
    .innerJoin(fieldCropAssignmentsTable, eq(harvestRecordsTable.fieldCropAssignmentId, fieldCropAssignmentsTable.id))
    .innerJoin(fieldsTable, eq(fieldCropAssignmentsTable.fieldId, fieldsTable.id))
    .innerJoin(cropVarietiesTable, eq(fieldCropAssignmentsTable.varietyId, cropVarietiesTable.id))
      .innerJoin(cropsTable, eq(cropVarietiesTable.cropId, cropsTable.id))
    .leftJoin(equipmentTable, eq(harvestRecordsTable.equipmentId, equipmentTable.id))
    .where(whereClause)
    .orderBy(desc(harvestRecordsTable.harvestDate));
  res.json({
    records: records.map((r) => ({
      ...r.harvest_records,
      fieldCropAssignment: r.field_crop_assignments,
      field: r.fields,
      crop: { ...r.crops, variety: r.crop_varieties?.variety ?? null },
      equipment: r.equipment,
    })),
  });
});

router.get("/farms/:farmId/harvests/:recordId", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const recordId = getRecordId(req);
  if (!recordId) { res.status(400).json({ error: "Invalid ID" }); return; }
  const rows = await db
    .select()
    .from(harvestRecordsTable)
    .innerJoin(fieldCropAssignmentsTable, eq(harvestRecordsTable.fieldCropAssignmentId, fieldCropAssignmentsTable.id))
    .innerJoin(fieldsTable, eq(fieldCropAssignmentsTable.fieldId, fieldsTable.id))
    .innerJoin(cropVarietiesTable, eq(fieldCropAssignmentsTable.varietyId, cropVarietiesTable.id))
      .innerJoin(cropsTable, eq(cropVarietiesTable.cropId, cropsTable.id))
    .leftJoin(equipmentTable, eq(harvestRecordsTable.equipmentId, equipmentTable.id))
    .where(and(eq(harvestRecordsTable.id, recordId), eq(fieldsTable.farmId, farmId)));
  if (!rows.length) { res.status(404).json({ error: "Not found" }); return; }
  const r = rows[0];
  res.json({ record: { ...r.harvest_records, field: r.fields, crop: { ...r.crops, variety: r.crop_varieties?.variety ?? null }, equipment: r.equipment } });
});

router.post("/farms/:farmId/harvests", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  let resolvedFieldId: number | null = null;
  if (req.body.fieldCropAssignmentId) {
    const [fca] = await db
      .select({ id: fieldCropAssignmentsTable.id, fieldId: fieldCropAssignmentsTable.fieldId })
      .from(fieldCropAssignmentsTable)
      .innerJoin(fieldsTable, eq(fieldCropAssignmentsTable.fieldId, fieldsTable.id))
      .where(and(eq(fieldCropAssignmentsTable.id, req.body.fieldCropAssignmentId), eq(fieldsTable.farmId, farmId)))
      .limit(1);
    if (!fca) { res.status(400).json({ error: "Field crop assignment not found on this farm" }); return; }
    resolvedFieldId = fca.fieldId;
  }
  // ── PHI (Pre-Harvest Interval) compliance check ──────────────────────────
  if (resolvedFieldId && req.body.harvestDate && !req.body.phiOverrideAcknowledged) {
    const harvestDate = new Date(req.body.harvestDate);
    const violations = await db
      .select({
        id: sprayApplicationsTable.id,
        applicationDate: sprayApplicationsTable.applicationDate,
        productName: sprayProductsTable.productName,
        harvestInterval: sprayProductsTable.harvestInterval,
      })
      .from(sprayApplicationsTable)
      .innerJoin(sprayProductsTable, eq(sprayApplicationsTable.productId, sprayProductsTable.id))
      .where(and(
        eq(sprayApplicationsTable.farmId, farmId),
        eq(sprayApplicationsTable.fieldId, resolvedFieldId),
        isNotNull(sprayProductsTable.harvestInterval),
      ));
    const activeViolations = violations.filter(v => {
      if (!v.harvestInterval) return false;
      const phiExpiry = new Date(v.applicationDate);
      phiExpiry.setDate(phiExpiry.getDate() + Number(v.harvestInterval));
      return phiExpiry > harvestDate;
    }).map(v => {
      const phiExpiry = new Date(v.applicationDate);
      phiExpiry.setDate(phiExpiry.getDate() + Number(v.harvestInterval));
      return {
        sprayId: v.id,
        productName: v.productName,
        applicationDate: v.applicationDate.toISOString().slice(0, 10),
        phiDays: Number(v.harvestInterval),
        phiExpiry: phiExpiry.toISOString().slice(0, 10),
      };
    });
    if (activeViolations.length > 0) {
      res.status(422).json({
        error: "phi_violation",
        message: `The harvest date falls within the Pre-Harvest Interval (PHI) of ${activeViolations.length} spray application${activeViolations.length > 1 ? "s" : ""} on this field.`,
        activePhiViolations: activeViolations,
      });
      return;
    }
  }
  const { equipmentId, operatorName, areaHarvestedHa, startTime, endTime, phiOverrideAcknowledged: _phi, ...rest } = req.body;
  if (!(await checkFieldAreaLimit(farmId, rest.fieldId ? Number(rest.fieldId) : null, areaHarvestedHa ? Number(areaHarvestedHa) : null, res, "Area harvested"))) return;
  const [record] = await db.insert(harvestRecordsTable).values({
    ...rest,
    equipmentId: equipmentId ? Number(equipmentId) : null,
    operatorName: operatorName || null,
    areaHarvestedHa: areaHarvestedHa || null,
    startTime: startTime || null,
    endTime: endTime || null,
  }).returning();

  // Auto-sync harvest yield → crop stock levels
  if (record.yieldTonnes && parseFloat(String(record.yieldTonnes)) > 0) {
    try {
      let commodity: string | null = (req.body.commodity as string) || null;
      let variety: string | null = (req.body.variety as string) || null;
      if (!commodity && record.fieldCropAssignmentId) {
        const [fca] = await db
          .select({ cropName: cropsTable.name, variety: cropVarietiesTable.variety })
          .from(fieldCropAssignmentsTable)
          .leftJoin(cropVarietiesTable, eq(fieldCropAssignmentsTable.varietyId, cropVarietiesTable.id))
          .leftJoin(cropsTable, eq(cropVarietiesTable.cropId, cropsTable.id))
          .where(eq(fieldCropAssignmentsTable.id, record.fieldCropAssignmentId))
          .limit(1);
        commodity = fca?.cropName ?? null;
        if (!variety) variety = fca?.variety ?? null;
      }
      if (commodity) {
        const harvestYear = new Date((record as any).harvestDate ?? Date.now()).getFullYear();
        const cropYear = `${harvestYear} Harvest`;
        const binId = req.body.binId ? Number(req.body.binId) : null;
        const yieldTonnes = parseFloat(String(record.yieldTonnes));
        const conditions = [
          eq(cropStockLevelsTable.farmId, farmId),
          eq(cropStockLevelsTable.commodity, commodity),
          eq(cropStockLevelsTable.cropYear, cropYear),
        ];
        if (binId !== null) {
          conditions.push(eq(cropStockLevelsTable.binId, binId));
        } else {
          conditions.push(isNull(cropStockLevelsTable.binId));
          if (variety) conditions.push(eq(cropStockLevelsTable.variety, variety));
        }
        const [existing] = await db.select().from(cropStockLevelsTable).where(and(...conditions)).limit(1);
        let stockLevelId: number;
        if (existing) {
          const newQty = parseFloat(String(existing.quantityTonnes)) + yieldTonnes;
          await db.update(cropStockLevelsTable)
            .set({ quantityTonnes: String(newQty), variety: variety ?? existing.variety, lastUpdated: new Date() })
            .where(eq(cropStockLevelsTable.id, existing.id));
          stockLevelId = existing.id;
        } else {
          const [newLevel] = await db.insert(cropStockLevelsTable)
            .values({ farmId, binId, commodity, variety, cropYear, quantityTonnes: String(yieldTonnes) })
            .returning();
          stockLevelId = newLevel.id;
        }
        await db.insert(cropStockMovementsTable).values({
          farmId, cropStockLevelId: stockLevelId, binId,
          movementType: "harvest_in", direction: "in",
          commodity, variety, cropYear,
          quantityTonnes: String(yieldTonnes),
          referenceType: "harvest_record", referenceId: record.id,
          performedBy: operatorName || null,
        });
      }
    } catch (e) {
      console.error("[harvest-stock-sync]", e);
    }
  }

  res.status(201).json({ record });
});

// ─── Crop Performance Comparison ───────────────────────
router.get("/farms/:farmId/crop-performance-comparison", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const varietyId = parseInt(req.query.varietyId as string, 10);
  if (isNaN(varietyId)) { res.status(400).json({ error: "varietyId is required" }); return; }

  const [variety] = await db.select({ id: cropVarietiesTable.id })
    .from(cropVarietiesTable)
    .where(and(eq(cropVarietiesTable.id, varietyId), eq(cropVarietiesTable.farmId, farmId)))
    .limit(1);
  if (!variety) { res.status(404).json({ error: "Variety not found" }); return; }

  const assignments = await db
    .select({
      id: fieldCropAssignmentsTable.id,
      fieldId: fieldCropAssignmentsTable.fieldId,
      fieldName: fieldsTable.name,
      fieldReference: fieldsTable.fieldReference,
      fieldAreaHectares: fieldsTable.areaHectares,
      year: fieldCropAssignmentsTable.year,
      season: fieldCropAssignmentsTable.season,
      plantingDate: fieldCropAssignmentsTable.plantingDate,
      expectedHarvestDate: fieldCropAssignmentsTable.expectedHarvestDate,
      actualHarvestDate: sql<string | null>`(
        SELECT MIN(${harvestRecordsTable.harvestDate})
        FROM ${harvestRecordsTable}
        WHERE ${harvestRecordsTable.fieldCropAssignmentId} = ${fieldCropAssignmentsTable.id}
      )`,
      totalYieldTonnes: sql<string | null>`(
        SELECT SUM(${harvestRecordsTable.yieldTonnes}::numeric)
        FROM ${harvestRecordsTable}
        WHERE ${harvestRecordsTable.fieldCropAssignmentId} = ${fieldCropAssignmentsTable.id}
      )`,
      totalAreaHarvestedHa: sql<string | null>`(
        SELECT SUM(${harvestRecordsTable.areaHarvestedHa}::numeric)
        FROM ${harvestRecordsTable}
        WHERE ${harvestRecordsTable.fieldCropAssignmentId} = ${fieldCropAssignmentsTable.id}
      )`,
      avgMoisturePercent: sql<string | null>`(
        SELECT ROUND(AVG(${harvestRecordsTable.moisturePercent}::numeric), 1)
        FROM ${harvestRecordsTable}
        WHERE ${harvestRecordsTable.fieldCropAssignmentId} = ${fieldCropAssignmentsTable.id}
          AND ${harvestRecordsTable.moisturePercent} IS NOT NULL
      )`,
      qualityGrades: sql<string | null>`(
        SELECT string_agg(DISTINCT ${harvestRecordsTable.qualityGrade}, ', ')
        FROM ${harvestRecordsTable}
        WHERE ${harvestRecordsTable.fieldCropAssignmentId} = ${fieldCropAssignmentsTable.id}
          AND ${harvestRecordsTable.qualityGrade} IS NOT NULL
      )`,
      harvestCount: sql<number>`(
        SELECT COUNT(*)
        FROM ${harvestRecordsTable}
        WHERE ${harvestRecordsTable.fieldCropAssignmentId} = ${fieldCropAssignmentsTable.id}
      )`,
    })
    .from(fieldCropAssignmentsTable)
    .innerJoin(fieldsTable, eq(fieldCropAssignmentsTable.fieldId, fieldsTable.id))
    .where(and(
      eq(fieldCropAssignmentsTable.varietyId, varietyId),
      eq(fieldsTable.farmId, farmId),
    ))
    .orderBy(desc(fieldCropAssignmentsTable.year), asc(fieldsTable.name));

  const comparisons = assignments.map(a => {
    const yieldT = a.totalYieldTonnes ? parseFloat(a.totalYieldTonnes) : null;
    const areaHaHarvested = a.totalAreaHarvestedHa ? parseFloat(a.totalAreaHarvestedHa) : null;
    const areaHaField = a.fieldAreaHectares ? parseFloat(String(a.fieldAreaHectares)) : null;
    const effectiveArea = (areaHaHarvested && areaHaHarvested > 0) ? areaHaHarvested : areaHaField;
    const yieldTha = (yieldT !== null && effectiveArea && effectiveArea > 0)
      ? Math.round((yieldT / effectiveArea) * 10) / 10
      : null;
    return { ...a, yieldTha, hasHarvest: yieldT !== null && yieldT > 0 };
  });

  const yieldValues = comparisons.filter(c => c.yieldTha !== null).map(c => c.yieldTha!);
  const farmAvgYieldTha = yieldValues.length > 0
    ? Math.round((yieldValues.reduce((s, v) => s + v, 0) / yieldValues.length) * 10) / 10
    : null;
  const maxYieldTha = yieldValues.length > 0 ? Math.max(...yieldValues) : null;
  const minYieldTha = yieldValues.length > 0 ? Math.min(...yieldValues) : null;

  res.json({ comparisons, farmAvgYieldTha, maxYieldTha, minYieldTha });
});

// ─── Crop Season Production Report ─────────────────────────────────────────
router.get("/farms/:farmId/crop-season-report", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const assignmentId = parseInt(req.query.assignmentId as string, 10);
  if (isNaN(assignmentId)) { res.status(400).json({ error: "assignmentId required" }); return; }

  // 1. Assignment + field + crop/variety
  const [asgn] = await db
    .select({
      id: fieldCropAssignmentsTable.id,
      fieldId: fieldCropAssignmentsTable.fieldId,
      varietyId: fieldCropAssignmentsTable.varietyId,
      plantingDate: fieldCropAssignmentsTable.plantingDate,
      expectedHarvestDate: fieldCropAssignmentsTable.expectedHarvestDate,
      seedRate: fieldCropAssignmentsTable.seedRate,
      seedUnit: fieldCropAssignmentsTable.seedUnit,
      season: fieldCropAssignmentsTable.season,
      year: fieldCropAssignmentsTable.year,
      notes: fieldCropAssignmentsTable.notes,
      fieldName: fieldsTable.name,
      fieldReference: fieldsTable.fieldReference,
      areaHectares: fieldsTable.areaHectares,
      soilType: fieldsTable.soilType,
      isOrganic: fieldsTable.isOrganic,
      isNvz: fieldsTable.isNvz,
      tenureType: fieldsTable.tenureType,
      annualRentPounds: fieldsTable.annualRentPounds,
      cropName: cropsTable.name,
      varietyName: cropVarietiesTable.variety,
      cropCategory: cropsTable.category,
    })
    .from(fieldCropAssignmentsTable)
    .innerJoin(fieldsTable, eq(fieldsTable.id, fieldCropAssignmentsTable.fieldId))
    .innerJoin(cropVarietiesTable, eq(cropVarietiesTable.id, fieldCropAssignmentsTable.varietyId))
    .innerJoin(cropsTable, eq(cropsTable.id, cropVarietiesTable.cropId))
    .where(and(eq(fieldCropAssignmentsTable.id, assignmentId), eq(fieldsTable.farmId, farmId)))
    .limit(1);

  if (!asgn) { res.status(404).json({ error: "Assignment not found" }); return; }

  const fieldId = asgn.fieldId;
  const year = asgn.year ?? new Date().getFullYear();
  const seasonStart = asgn.plantingDate ?? new Date(`${year}-01-01`);
  const seasonEnd = new Date();

  // 2. Fetch all data in parallel
  const [sprays, operations, fertiliser, seedDrilling, fuelUsage, harvests, soilTests, sisterAssignments, irrigation, monthlyRainfall] = await Promise.all([
    db.select({
      id: sprayApplicationsTable.id,
      applicationDate: sprayApplicationsTable.applicationDate,
      productName: sprayProductsTable.productName,
      activeIngredient: sprayProductsTable.activeIngredient,
      category: sprayProductsTable.category,
      applicationRate: sprayApplicationsTable.applicationRate,
      rateUnit: sprayApplicationsTable.rateUnit,
      areaSprayedHa: sprayApplicationsTable.areaSprayedHa,
      waterVolumeLitres: sprayApplicationsTable.waterVolumeLitres,
      operatorName: sprayApplicationsTable.operatorName,
      equipmentUsed: sprayApplicationsTable.equipmentUsed,
      reasonForApplication: sprayApplicationsTable.reasonForApplication,
      growthStage: sprayApplicationsTable.growthStage,
      targetCrop: sprayApplicationsTable.targetCrop,
      bufferZoneMetres: sprayApplicationsTable.bufferZoneMetres,
      notes: sprayApplicationsTable.notes,
      productCostPencePerUnit: sprayApplicationsTable.productCostPencePerUnit,
      batchNumber: sprayApplicationsTable.batchNumber,
      lotNumber: sprayApplicationsTable.lotNumber,
      stockDeliveryId: sprayApplicationsTable.stockDeliveryId,
    })
    .from(sprayApplicationsTable)
    .innerJoin(sprayProductsTable, eq(sprayProductsTable.id, sprayApplicationsTable.productId))
    .where(and(
      eq(sprayApplicationsTable.farmId, farmId),
      eq(sprayApplicationsTable.fieldId, fieldId),
      gte(sprayApplicationsTable.applicationDate, seasonStart),
      lte(sprayApplicationsTable.applicationDate, seasonEnd),
    ))
    .orderBy(asc(sprayApplicationsTable.applicationDate)),

    db.select().from(fieldOperationsTable)
    .where(and(
      eq(fieldOperationsTable.farmId, farmId),
      eq(fieldOperationsTable.fieldId, fieldId),
      gte(fieldOperationsTable.operationDate, seasonStart),
      lte(fieldOperationsTable.operationDate, seasonEnd),
    ))
    .orderBy(asc(fieldOperationsTable.operationDate)),

    db.select().from(nvzFertiliserApplicationsTable)
    .where(and(
      eq(nvzFertiliserApplicationsTable.farmId, farmId),
      eq(nvzFertiliserApplicationsTable.fieldId, fieldId),
      gte(nvzFertiliserApplicationsTable.applicationDate, seasonStart),
      lte(nvzFertiliserApplicationsTable.applicationDate, seasonEnd),
    ))
    .orderBy(asc(nvzFertiliserApplicationsTable.applicationDate)),

    db.select().from(seedDrillingRecordsTable)
    .where(and(
      eq(seedDrillingRecordsTable.farmId, farmId),
      eq(seedDrillingRecordsTable.fieldId, fieldId),
      gte(seedDrillingRecordsTable.drillingDate, seasonStart),
      lte(seedDrillingRecordsTable.drillingDate, seasonEnd),
    ))
    .orderBy(asc(seedDrillingRecordsTable.drillingDate)),

    db.select({
      id: fuelUsageTable.id,
      usageDate: fuelUsageTable.usageDate,
      quantityLitres: fuelUsageTable.quantityLitres,
      purpose: fuelUsageTable.purpose,
      vehicleName: fuelUsageTable.vehicleName,
      tankName: fuelUsageTable.tankName,
      notes: fuelUsageTable.notes,
      costPencePerLitre: fuelUsageTable.costPencePerLitre,
    })
    .from(fuelUsageTable)
    .where(and(
      eq(fuelUsageTable.farmId, farmId),
      eq(fuelUsageTable.fieldId, fieldId),
      gte(fuelUsageTable.usageDate, seasonStart),
      lte(fuelUsageTable.usageDate, seasonEnd),
    ))
    .orderBy(asc(fuelUsageTable.usageDate)),

    db.select().from(harvestRecordsTable)
    .where(eq(harvestRecordsTable.fieldCropAssignmentId, assignmentId))
    .orderBy(asc(harvestRecordsTable.harvestDate)),

    db.select({
      id: soilTestRecordsTable.id,
      sampleDate: soilTestRecordsTable.sampleDate,
      sampleReference: soilTestRecordsTable.sampleReference,
      laboratory: soilTestRecordsTable.laboratory,
      status: soilTestRecordsTable.status,
      sampleDepthCm: soilTestRecordsTable.sampleDepthCm,
      sampledBy: soilTestRecordsTable.sampledBy,
      notes: soilTestRecordsTable.notes,
    })
    .from(soilTestRecordsTable)
    .where(and(eq(soilTestRecordsTable.farmId, farmId), eq(soilTestRecordsTable.fieldId, fieldId)))
    .orderBy(desc(soilTestRecordsTable.sampleDate))
    .limit(3),

    asgn.varietyId && asgn.year
      ? db.select({
          id: fieldCropAssignmentsTable.id,
          fieldName: fieldsTable.name,
          fieldReference: fieldsTable.fieldReference,
          areaHectares: fieldsTable.areaHectares,
          plantingDate: fieldCropAssignmentsTable.plantingDate,
          expectedHarvestDate: fieldCropAssignmentsTable.expectedHarvestDate,
        })
        .from(fieldCropAssignmentsTable)
        .innerJoin(fieldsTable, eq(fieldsTable.id, fieldCropAssignmentsTable.fieldId))
        .where(and(
          eq(fieldCropAssignmentsTable.varietyId, asgn.varietyId!),
          eq(fieldCropAssignmentsTable.year, asgn.year!),
          eq(fieldsTable.farmId, farmId),
          ne(fieldCropAssignmentsTable.id, assignmentId),
        ))
      : Promise.resolve([] as Array<{ id: number; fieldName: string; fieldReference: string | null; areaHectares: string | null; plantingDate: Date | null; expectedHarvestDate: Date | null; }>),

    // 9. Irrigation events for this farm during the season (no fieldId column — filtered by date)
    db.select({
      id: irrigationRecordsTable.id,
      irrigationDate: irrigationRecordsTable.irrigationDate,
      fieldOrBlockDescription: irrigationRecordsTable.fieldOrBlockDescription,
      areaIrrigatedHa: irrigationRecordsTable.areaIrrigatedHa,
      cropType: irrigationRecordsTable.cropType,
      growthStage: irrigationRecordsTable.growthStage,
      irrigationMethod: irrigationRecordsTable.irrigationMethod,
      applicationDepthMm: irrigationRecordsTable.applicationDepthMm,
      volumeAppliedM3: irrigationRecordsTable.volumeAppliedM3,
      soilMoistureDeficitMm: irrigationRecordsTable.soilMoistureDeficitMm,
      rainfallLast7DaysMm: irrigationRecordsTable.rainfallLast7DaysMm,
      operatorName: irrigationRecordsTable.operatorName,
      notes: irrigationRecordsTable.notes,
    })
    .from(irrigationRecordsTable)
    .where(and(
      eq(irrigationRecordsTable.farmId, farmId),
      gte(irrigationRecordsTable.irrigationDate, seasonStart.toISOString().slice(0, 10)),
      lte(irrigationRecordsTable.irrigationDate, seasonEnd.toISOString().slice(0, 10)),
    ))
    .orderBy(asc(irrigationRecordsTable.irrigationDate)),

    // 10. Monthly rainfall aggregates from weather stations (field-linked or farm-wide)
    db.select({
      month: sql<string>`date_trunc('month', ${weatherReadingsTable.readingTimestamp})::text`,
      totalRainfallMm: sql<string>`COALESCE(SUM(${weatherReadingsTable.rainfallMm}), 0)::text`,
      avgTempC: sql<string>`ROUND(AVG(${weatherReadingsTable.temperatureC})::numeric, 1)::text`,
      maxTempC: sql<string>`MAX(${weatherReadingsTable.temperatureHighC})::text`,
      minTempC: sql<string>`MIN(${weatherReadingsTable.temperatureLowC})::text`,
      readingCount: sql<number>`COUNT(*)::int`,
    })
    .from(weatherReadingsTable)
    .where(and(
      eq(weatherReadingsTable.farmId, farmId),
      or(eq(weatherReadingsTable.fieldId, fieldId), isNull(weatherReadingsTable.fieldId)),
      gte(weatherReadingsTable.readingTimestamp, seasonStart),
      lte(weatherReadingsTable.readingTimestamp, seasonEnd),
    ))
    .groupBy(sql`date_trunc('month', ${weatherReadingsTable.readingTimestamp})`)
    .orderBy(sql`date_trunc('month', ${weatherReadingsTable.readingTimestamp})`),
  ]);

  // Field season expenses (agronomy, drying, haulage, etc.)
  const fieldSeasonExpenses = await db.select().from(fieldSeasonExpensesTable)
    .where(eq(fieldSeasonExpensesTable.fieldCropAssignmentId, assignmentId))
    .orderBy(asc(fieldSeasonExpensesTable.expenseDate));

  // Enrich soil tests with results; enrich sisters with harvests
  const [soilTestResults, sisterHarvestRows] = await Promise.all([
    soilTests.length > 0
      ? db.select().from(soilTestResultsTable).where(inArray(soilTestResultsTable.soilTestId, soilTests.map(t => t.id)))
      : Promise.resolve([] as (typeof soilTestResultsTable.$inferSelect)[]),
    sisterAssignments.length > 0
      ? db.select().from(harvestRecordsTable).where(inArray(harvestRecordsTable.fieldCropAssignmentId, sisterAssignments.map(s => s.id)))
      : Promise.resolve([] as (typeof harvestRecordsTable.$inferSelect)[]),
  ]);

  const soilTestsEnriched = soilTests.map(t => ({ ...t, results: soilTestResults.filter(r => r.soilTestId === t.id) }));

  const sisterFields = sisterAssignments.map(s => {
    const sh = sisterHarvestRows.filter(h => h.fieldCropAssignmentId === s.id);
    const totalYield = sh.reduce((sum, h) => sum + (h.yieldTonnes ? parseFloat(h.yieldTonnes) : 0), 0);
    const totalArea = sh.reduce((sum, h) => sum + (h.areaHarvestedHa ? parseFloat(h.areaHarvestedHa) : 0), 0);
    const areaHa = parseFloat(String(s.areaHectares ?? 0));
    return {
      ...s,
      harvests: sh,
      totalYieldTonnes: totalYield,
      yieldTha: totalArea > 0 ? totalYield / totalArea : (areaHa > 0 ? totalYield / areaHa : null),
    };
  });

  // Summary totals
  const totalYieldTonnes = harvests.reduce((s, h) => s + (h.yieldTonnes ? parseFloat(h.yieldTonnes) : 0), 0);
  const totalAreaHarvestedHa = harvests.reduce((s, h) => s + (h.areaHarvestedHa ? parseFloat(h.areaHarvestedHa) : 0), 0);
  const fieldAreaHa = asgn.areaHectares ? parseFloat(String(asgn.areaHectares)) : null;
  const effectiveArea = totalAreaHarvestedHa > 0 ? totalAreaHarvestedHa : fieldAreaHa;

  const totalMachineHours = operations.reduce((s, op) => s + (op.machineHours ? parseFloat(String(op.machineHours)) : 0), 0);
  const totalLabourHours = operations.reduce((s, op) => s + (op.labourHours ? parseFloat(String(op.labourHours)) : 0), 0);
  const totalMachineCostPence = operations.reduce((s, op) => {
    if (op.isContractor && op.contractorCostPence) return s + op.contractorCostPence;
    return s + (op.machineHours && op.machineRatePence ? parseFloat(String(op.machineHours)) * op.machineRatePence : 0);
  }, 0);
  const totalLabourCostPence = operations.reduce((s, op) => s + (op.labourHours && op.labourRatePence ? parseFloat(String(op.labourHours)) * op.labourRatePence : 0), 0);
  const totalFuelLitres = fuelUsage.reduce((s, f) => s + parseFloat(String(f.quantityLitres)), 0);
  const totalFuelCostPence = fuelUsage.reduce((s, f) => {
    if (!f.costPencePerLitre) return s;
    return s + Math.round(parseFloat(String(f.quantityLitres)) * f.costPencePerLitre);
  }, 0);
  const totalNitrogenKg = fertiliser.reduce((s, f) => s + (f.totalNitrogenKg ? parseFloat(String(f.totalNitrogenKg)) : 0), 0);
  const totalRainfallMm = monthlyRainfall.reduce((s, m) => s + parseFloat(String(m.totalRainfallMm ?? 0)), 0);
  const totalIrrigationMm = irrigation.reduce((s, i) => s + (i.applicationDepthMm ? parseFloat(String(i.applicationDepthMm)) : 0), 0);
  const totalIrrigationM3 = irrigation.reduce((s, i) => s + (i.volumeAppliedM3 ? parseFloat(String(i.volumeAppliedM3)) : 0), 0);

  // Financial summary
  const totalFertiliserCostPence = fertiliser.reduce((s, f) => {
    // Use delivery-linked calculation if available, otherwise fall back to manually entered total
    if (f.unitCostPencePerTonne && f.applicationRateKgHa && f.areaAppliedHa) {
      return s + Math.round(Number(f.unitCostPencePerTonne) * parseFloat(String(f.applicationRateKgHa)) / 1000 * parseFloat(String(f.areaAppliedHa)));
    }
    return s + (f.totalCostPence ?? 0);
  }, 0);
  const totalSeedCostPence = seedDrilling.reduce((s, d) => {
    if (!d.seedCostPencePerKg || !d.seedRate || !d.areaSeededHa) return s;
    return s + Math.round(Number(d.seedCostPencePerKg) * parseFloat(String(d.seedRate)) * parseFloat(String(d.areaSeededHa)));
  }, 0);
  const totalSprayCostPence = sprays.reduce((s, sp) => {
    if (!sp.productCostPencePerUnit || !sp.applicationRate || !sp.areaSprayedHa) return s;
    return s + Math.round(Number(sp.productCostPencePerUnit) * parseFloat(String(sp.applicationRate)) * parseFloat(String(sp.areaSprayedHa)));
  }, 0);
  const totalRevenuePence = harvests.reduce((s, h) => {
    if (!h.salePricePerTonnePence || !h.yieldTonnes) return s;
    return s + Math.round(h.salePricePerTonnePence * parseFloat(String(h.yieldTonnes)));
  }, 0);
  // Prorated field rent (if rented, prorate annual rent over the season duration)
  const isRented = asgn.tenureType === "rented" || asgn.tenureType === "tenanted" || asgn.tenureType === "fbt";
  const annualRentPoundsVal = asgn.annualRentPounds ? parseFloat(String(asgn.annualRentPounds)) : 0;
  let proratedRentPence = 0;
  if (isRented && annualRentPoundsVal > 0) {
    const seasonMs = seasonEnd.getTime() - seasonStart.getTime();
    const seasonDays = Math.max(seasonMs / (1000 * 60 * 60 * 24), 1);
    proratedRentPence = Math.round(annualRentPoundsVal * (seasonDays / 365) * 100);
  }

  // Miscellaneous field season expenses
  const totalMiscExpensesPence = fieldSeasonExpenses.reduce((s, e) => s + (e.amountPence ?? 0), 0);

  const totalInputCostPence = totalMachineCostPence + totalLabourCostPence + totalFertiliserCostPence + totalSeedCostPence + totalSprayCostPence + totalFuelCostPence + proratedRentPence + totalMiscExpensesPence;
  const grossMarginPence = totalRevenuePence - totalInputCostPence;

  res.json({
    assignment: asgn,
    sprays,
    operations,
    fertiliser,
    seedDrilling,
    fuelUsage,
    harvests,
    soilTests: soilTestsEnriched,
    sisterFields,
    irrigation,
    monthlyRainfall,
    fieldExpenses: fieldSeasonExpenses,
    generatedAt: new Date().toISOString(),
    summary: {
      totalYieldTonnes,
      yieldTha: effectiveArea && effectiveArea > 0 ? totalYieldTonnes / effectiveArea : null,
      totalAreaHarvestedHa,
      totalSprayApplications: sprays.length,
      totalOperations: operations.length,
      totalMachineHours,
      totalLabourHours,
      totalMachineCostPence,
      totalLabourCostPence,
      totalFuelLitres,
      totalNitrogenKg,
      totalRainfallMm,
      totalIrrigationMm,
      totalIrrigationM3,
      totalIrrigationEvents: irrigation.length,
      weatherMonthsRecorded: monthlyRainfall.length,
      totalFertiliserCostPence,
      totalSeedCostPence,
      totalSprayCostPence,
      totalFuelCostPence,
      proratedRentPence,
      totalMiscExpensesPence,
      totalRevenuePence,
      totalInputCostPence,
      grossMarginPence,
    },
  });
});

// ─── Field Season Expenses CRUD ───────────────────────────────────────────────
router.get("/farms/:farmId/field-season-expenses", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const assignmentId = parseInt(Array.isArray(req.query.assignmentId) ? (req.query.assignmentId[0] as string) : (req.query.assignmentId as string), 10);
  if (isNaN(assignmentId)) { res.status(400).json({ error: "assignmentId required" }); return; }
  const expenses = await db.select().from(fieldSeasonExpensesTable)
    .where(and(eq(fieldSeasonExpensesTable.farmId, farmId), eq(fieldSeasonExpensesTable.fieldCropAssignmentId, assignmentId)))
    .orderBy(asc(fieldSeasonExpensesTable.expenseDate));
  res.json({ expenses });
});

router.post("/farms/:farmId/field-season-expenses", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const body = sanitiseBody(req.body as Record<string, unknown>);
  const [expense] = await db.insert(fieldSeasonExpensesTable).values({ ...body, farmId } as typeof fieldSeasonExpensesTable.$inferInsert).returning();
  res.status(201).json({ expense });
});

