router.post("/farms/:farmId/spray-applications", requireAuth, requireTenant, requireModuleByKey("sprays-inputs", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  if (!(await checkFieldAreaLimit(farmId, req.body.fieldId ? Number(req.body.fieldId) : null, req.body.areaSprayedHa ? Number(req.body.areaSprayedHa) : null, res, "Area sprayed"))) return;
  const sprayBody = sanitiseBody(req.body as Record<string, unknown>);
  // When a linked member ID is provided, derive operatorName from the member record so the
  // two fields never diverge (e.g. after a name change or when records are created via API).
  if (sprayBody.operatorMemberId) {
    const [member] = await db
      .select({ firstName: farmMembersTable.firstName, lastName: farmMembersTable.lastName })
      .from(farmMembersTable)
      .where(and(eq(farmMembersTable.id, Number(sprayBody.operatorMemberId)), eq(farmMembersTable.farmId, farmId)))
      .limit(1);
    if (member) {
      sprayBody.operatorName = [member.firstName, member.lastName].filter(Boolean).join(" ").trim() || sprayBody.operatorName;
    }
  }
  // Auto-populate productCostPencePerUnit from delivery when not explicitly provided
  if (sprayBody.stockDeliveryId && !sprayBody.productCostPencePerUnit) {
    const [del] = await db.select().from(stockDeliveriesTable).where(eq(stockDeliveriesTable.id, Number(sprayBody.stockDeliveryId))).limit(1);
    if (del?.costPence && del?.quantity && parseFloat(String(del.quantity)) > 0) {
      sprayBody.productCostPencePerUnit = Math.round(Number(del.costPence) / parseFloat(String(del.quantity)));
    }
  }
  // ── Season application count check (per field) ──────────────────────────────
  let seasonWarning: string | null = null;
  if (req.body.productId && req.body.fieldId) {
    const [prod] = await db.select({ maxApps: sprayProductsTable.maxApplicationsPerSeason, productName: sprayProductsTable.productName })
      .from(sprayProductsTable).where(eq(sprayProductsTable.id, Number(req.body.productId))).limit(1);
    if (prod?.maxApps) {
      const appDate = req.body.applicationDate ? new Date(String(req.body.applicationDate)) : new Date();
      const yr = appDate.getMonth() >= 7 ? appDate.getFullYear() : appDate.getFullYear() - 1;
      const seasonStart = new Date(yr, 7, 1);
      const seasonEnd = new Date(yr + 1, 6, 31, 23, 59, 59);
      const [countRow] = await db.select({ cnt: sql<number>`count(*)::int` }).from(sprayApplicationsTable)
        .where(and(
          eq(sprayApplicationsTable.farmId, farmId),
          eq(sprayApplicationsTable.productId, Number(req.body.productId)),
          eq(sprayApplicationsTable.fieldId, Number(req.body.fieldId)),
          gte(sprayApplicationsTable.applicationDate, seasonStart),
          lte(sprayApplicationsTable.applicationDate, seasonEnd)
        ));
      const currentCount = countRow?.cnt ?? 0;
      if (currentCount >= prod.maxApps) {
        seasonWarning = `${prod.productName} has a maximum of ${prod.maxApps} application${prod.maxApps !== 1 ? "s" : ""} per season per field. This field has already received ${currentCount} application${currentCount !== 1 ? "s" : ""} this season.`;
      }
    }
  }

  const [record] = await db.insert(sprayApplicationsTable).values({ ...sprayBody, farmId }).returning();

  const rate = parseFloat(req.body.applicationRate);
  const area = parseFloat(req.body.areaSprayedHa);
  if (!isNaN(rate) && !isNaN(area) && area > 0 && req.body.productId) {
    const [product] = await db.select().from(sprayProductsTable).where(eq(sprayProductsTable.id, Number(req.body.productId))).limit(1);
    if (product?.stockItemId) {
      const qtyUsed = rate * area;
      const qtyChange = -qtyUsed;
      await db.insert(stockMovementsTable).values({
        farmId,
        stockItemId: product.stockItemId,
        movementType: "usage",
        quantityChange: String(qtyChange),
        referenceType: "spray_application",
        referenceId: record.id,
        fieldId: req.body.fieldId ? Number(req.body.fieldId) : null,
        performedBy: req.body.operatorName || null,
        notes: `Auto-deducted: spray application on ${req.body.applicationDate}`,
      });
      const [existing] = await db.select().from(stockLevelsTable).where(and(eq(stockLevelsTable.farmId, farmId), eq(stockLevelsTable.stockItemId, product.stockItemId))).limit(1);
      if (existing) {
        await db.update(stockLevelsTable).set({ currentQuantity: String(parseFloat(existing.currentQuantity) + qtyChange), lastUpdated: new Date() }).where(eq(stockLevelsTable.id, existing.id));
      } else {
        await db.insert(stockLevelsTable).values({ farmId, stockItemId: product.stockItemId, currentQuantity: String(qtyChange) });
      }
    }
  }

  res.status(201).json({ record, seasonWarning });
});

router.put("/farms/:farmId/spray-applications/:recordId", requireAuth, requireTenant, requireModuleByKey("sprays-inputs", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const recordId = getRecordId(req);
  if (!recordId) { res.status(400).json({ error: "Invalid ID" }); return; }

  // Fetch existing record to calculate old deduction
  const [existing] = await db.select().from(sprayApplicationsTable).where(and(eq(sprayApplicationsTable.id, recordId), eq(sprayApplicationsTable.farmId, farmId))).limit(1);
  if (!existing) { res.status(404).json({ error: "Not found" }); return; }

  const putSprayFieldId = req.body.fieldId ? Number(req.body.fieldId) : (existing.fieldId ?? null);
  const putSprayAreaHa = req.body.areaSprayedHa ? Number(req.body.areaSprayedHa) : (existing.areaSprayedHa ? Number(existing.areaSprayedHa) : null);
  if (!(await checkFieldAreaLimit(farmId, putSprayFieldId, putSprayAreaHa, res, "Area sprayed"))) return;

  const putSprayBody = sanitiseBody(req.body as Record<string, unknown>);
  // When a linked member ID is provided, derive operatorName from the member record so the
  // two fields never diverge (e.g. after a name change or when records are edited via API).
  if (putSprayBody.operatorMemberId) {
    const [member] = await db
      .select({ firstName: farmMembersTable.firstName, lastName: farmMembersTable.lastName })
      .from(farmMembersTable)
      .where(and(eq(farmMembersTable.id, Number(putSprayBody.operatorMemberId)), eq(farmMembersTable.farmId, farmId)))
      .limit(1);
    if (member) {
      putSprayBody.operatorName = [member.firstName, member.lastName].filter(Boolean).join(" ").trim() || putSprayBody.operatorName;
    }
  }
  const [record] = await db.update(sprayApplicationsTable).set(putSprayBody).where(and(eq(sprayApplicationsTable.id, recordId), eq(sprayApplicationsTable.farmId, farmId))).returning();
  if (!record) { res.status(404).json({ error: "Not found" }); return; }

  // Reconcile stock if productId, applicationRate, or areaSprayedHa changed
  const oldRate = parseFloat(existing.applicationRate ?? "0");
  const oldArea = parseFloat(existing.areaSprayedHa ?? "0");
  const newRate = parseFloat(record.applicationRate ?? "0");
  const newArea = parseFloat(record.areaSprayedHa ?? "0");
  const oldQty = !isNaN(oldRate) && !isNaN(oldArea) ? oldRate * oldArea : 0;
  const newQty = !isNaN(newRate) && !isNaN(newArea) ? newRate * newArea : 0;
  const oldProdId = existing.productId;
  const newProdId = record.productId;

  const stockChanged = oldProdId !== newProdId || Math.abs(oldQty - newQty) > 0.0001;
  if (stockChanged) {
    // Reverse old deduction
    if (oldProdId && oldQty > 0) {
      const [oldProduct] = await db.select().from(sprayProductsTable).where(eq(sprayProductsTable.id, oldProdId)).limit(1);
      if (oldProduct?.stockItemId) {
        await db.insert(stockMovementsTable).values({ farmId, stockItemId: oldProduct.stockItemId, movementType: "adjustment", quantityChange: String(oldQty), referenceType: "spray_application", referenceId: recordId, notes: `Stock reversal: spray application ${recordId} edited` });
        const [level] = await db.select().from(stockLevelsTable).where(and(eq(stockLevelsTable.farmId, farmId), eq(stockLevelsTable.stockItemId, oldProduct.stockItemId))).limit(1);
        if (level) await db.update(stockLevelsTable).set({ currentQuantity: String(parseFloat(level.currentQuantity) + oldQty), lastUpdated: new Date() }).where(eq(stockLevelsTable.id, level.id));
      }
    }
    // Apply new deduction
    if (newProdId && newQty > 0) {
      const [newProduct] = await db.select().from(sprayProductsTable).where(eq(sprayProductsTable.id, newProdId)).limit(1);
      if (newProduct?.stockItemId) {
        const qtyChange = -newQty;
        await db.insert(stockMovementsTable).values({ farmId, stockItemId: newProduct.stockItemId, movementType: "usage", quantityChange: String(qtyChange), referenceType: "spray_application", referenceId: recordId, fieldId: record.fieldId ? Number(record.fieldId) : null, performedBy: record.operatorName || null, notes: `Auto-deducted: spray application on ${record.applicationDate} (edited)` });
        const [level] = await db.select().from(stockLevelsTable).where(and(eq(stockLevelsTable.farmId, farmId), eq(stockLevelsTable.stockItemId, newProduct.stockItemId))).limit(1);
        if (level) { await db.update(stockLevelsTable).set({ currentQuantity: String(parseFloat(level.currentQuantity) + qtyChange), lastUpdated: new Date() }).where(eq(stockLevelsTable.id, level.id)); } else { await db.insert(stockLevelsTable).values({ farmId, stockItemId: newProduct.stockItemId, currentQuantity: String(qtyChange) }); }
      }
    }
  }

  res.json({ record });
});

router.delete("/farms/:farmId/spray-applications/:recordId", requireAuth, requireTenant, requireModuleByKey("sprays-inputs", "delete"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const recordId = getRecordId(req);
  if (!recordId) { res.status(400).json({ error: "Invalid ID" }); return; }

  // Reverse stock deduction before deleting
  const [existing] = await db.select().from(sprayApplicationsTable).where(and(eq(sprayApplicationsTable.id, recordId), eq(sprayApplicationsTable.farmId, farmId))).limit(1);
  if (existing?.productId) {
    const rate = parseFloat(existing.applicationRate ?? "0");
    const area = parseFloat(existing.areaSprayedHa ?? "0");
    if (!isNaN(rate) && !isNaN(area) && rate > 0 && area > 0) {
      const qtyUsed = rate * area;
      const [product] = await db.select().from(sprayProductsTable).where(eq(sprayProductsTable.id, existing.productId)).limit(1);
      if (product?.stockItemId) {
        await db.insert(stockMovementsTable).values({ farmId, stockItemId: product.stockItemId, movementType: "adjustment", quantityChange: String(qtyUsed), referenceType: "spray_application", referenceId: recordId, notes: `Stock reversal: spray application ${recordId} deleted` });
        const [level] = await db.select().from(stockLevelsTable).where(and(eq(stockLevelsTable.farmId, farmId), eq(stockLevelsTable.stockItemId, product.stockItemId))).limit(1);
        if (level) await db.update(stockLevelsTable).set({ currentQuantity: String(parseFloat(level.currentQuantity) + qtyUsed), lastUpdated: new Date() }).where(eq(stockLevelsTable.id, level.id));
      }
    }
  }

  await db.delete(sprayApplicationsTable).where(and(eq(sprayApplicationsTable.id, recordId), eq(sprayApplicationsTable.farmId, farmId)));
  res.json({ success: true });
});

