// ─── Animal Profile (aggregated per-animal view) ──────────────────────────────
router.get("/farms/:farmId/animals/:recordId/profile", requireAuth, requireTenant, requireModuleByKey("livestock-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const recordId = getRecordId(req);
  if (!recordId) { res.status(400).json({ error: "Invalid ID" }); return; }

  const [animal] = await db.select().from(livestockAnimalsTable).where(and(eq(livestockAnimalsTable.id, recordId), eq(livestockAnimalsTable.farmId, farmId)));
  if (!animal) { res.status(404).json({ error: "Animal not found" }); return; }

  const herd = animal.herdId
    ? (await db.select().from(herdFlockRegisterTable).where(eq(herdFlockRegisterTable.id, animal.herdId)).limit(1))[0] ?? null
    : null;

  const [directMedicines, herdMedicines, movements, calvings, mastitis, mortalityRows, allFarmIncidents] = await Promise.all([
    // Direct: medicine records linked to this specific animal
    db.select().from(livestockMedicineRecordsTable)
      .where(and(eq(livestockMedicineRecordsTable.farmId, farmId), eq(livestockMedicineRecordsTable.animalId, recordId)))
      .orderBy(desc(livestockMedicineRecordsTable.administeredDate)),
    // Indirect: group/whole-herd treatments for this animal's herd.
    // Also includes legacy records where treatment_scope is NULL (treated as whole_herd).
    animal.herdId
      ? db.select().from(livestockMedicineRecordsTable)
          .where(and(
            eq(livestockMedicineRecordsTable.farmId, farmId),
            eq(livestockMedicineRecordsTable.herdId, animal.herdId),
            or(
              inArray(livestockMedicineRecordsTable.treatmentScope, ["group", "whole_herd"]),
              isNull(livestockMedicineRecordsTable.treatmentScope),
            ),
          ))
          .orderBy(desc(livestockMedicineRecordsTable.administeredDate))
      : Promise.resolve([]),
    db.select().from(livestockMovementsTable)
      .where(and(eq(livestockMovementsTable.farmId, farmId), eq(livestockMovementsTable.animalId, recordId)))
      .orderBy(desc(livestockMovementsTable.movementDate)),
    db.select().from(dairyCalvingRecordsTable)
      .where(and(eq(dairyCalvingRecordsTable.farmId, farmId), eq(dairyCalvingRecordsTable.cowAnimalId, recordId)))
      .orderBy(desc(dairyCalvingRecordsTable.calvingDate)),
    db.select().from(dairyMastitisRecordsTable)
      .where(and(eq(dairyMastitisRecordsTable.farmId, farmId), eq(dairyMastitisRecordsTable.animalId, recordId)))
      .orderBy(desc(dairyMastitisRecordsTable.onsetDate)),
    db.select({
        id: livestockMortalityTable.id,
        tagNumber: livestockMortalityTable.tagNumber,
        species: livestockMortalityTable.species,
        breed: livestockMortalityTable.breed,
        dateOfDeath: livestockMortalityTable.dateOfDeath,
        causeOfDeath: livestockMortalityTable.causeOfDeath,
        disposalMethod: livestockMortalityTable.disposalMethod,
        disposalOperator: livestockMortalityTable.disposalOperator,
        disposalRef: livestockMortalityTable.disposalRef,
        veterinaryAttended: livestockMortalityTable.veterinaryAttended,
        vetName: livestockMortalityTable.vetName,
        postMortemCarriedOut: livestockMortalityTable.postMortemCarriedOut,
        postMortemFindings: livestockMortalityTable.postMortemFindings,
        bcmsNotified: livestockMortalityTable.bcmsNotified,
        bcmsNotificationRef: livestockMortalityTable.bcmsNotificationRef,
        notes: livestockMortalityTable.notes,
        contractorId: livestockMortalityTable.contractorId,
        contractorName: fallenStockContractorsTable.name,
        contractorApprovalNumber: fallenStockContractorsTable.approvalNumber,
        contractorOperatorType: fallenStockContractorsTable.operatorType,
      })
      .from(livestockMortalityTable)
      .leftJoin(fallenStockContractorsTable, eq(livestockMortalityTable.contractorId, fallenStockContractorsTable.id))
      .where(and(eq(livestockMortalityTable.farmId, farmId), eq(livestockMortalityTable.animalId, recordId)))
      .limit(1),
    // All disease incidents for the farm — filtered below by animal ID
    db.select().from(diseaseIncidentLogTable)
      .where(eq(diseaseIncidentLogTable.farmId, farmId))
      .orderBy(desc(diseaseIncidentLogTable.incidentDate)),
  ]);

  // Disease incidents this specific animal was involved in (affected or mortality)
  const diseaseIncidents = allFarmIncidents.filter(i => {
    const affected = parseMortalityIds(i.affectedAnimalIds);
    const mortality = parseMortalityIds(i.mortalityAnimalIds);
    return affected.includes(recordId) || mortality.includes(recordId);
  }).map(i => ({
    ...i,
    _involvedAs: parseMortalityIds(i.mortalityAnimalIds).includes(recordId) ? "mortality" : "affected",
  }));

  // For group-scope herd records, only include this animal if its ear tag appears
  // in the verified treatedAnimalTags list (these are validated tags saved by the UI).
  // For whole_herd scope, all animals in the herd are included unconditionally.
  const animalEarTag = (animal.earTagNumber ?? "").toLowerCase();
  const animalTagNumber = (animal.tagNumber ?? "").toLowerCase();
  const filteredHerdMedicines = (herdMedicines as any[]).filter((m: any) => {
    // NULL treatment_scope = legacy record predating the scope column; treat as whole_herd
    if (m.treatmentScope === "whole_herd" || m.treatmentScope === null) return true;
    if (m.treatmentScope === "group") {
      if (!m.treatedAnimalTags) return false; // no verified tags — cannot link
      const verifiedTags = m.treatedAnimalTags.split(",").map((t: string) => t.trim().toLowerCase());
      return (animalEarTag && verifiedTags.includes(animalEarTag)) ||
             (animalTagNumber && verifiedTags.includes(animalTagNumber));
    }
    return false;
  });

  // Merge direct and filtered herd-level records, deduplicate by id, sort newest first
  const seenIds = new Set<number>();
  const medicines = [...directMedicines, ...filteredHerdMedicines]
    .filter(m => { if (seenIds.has(m.id)) return false; seenIds.add(m.id); return true; })
    .sort((a, b) => new Date(b.administeredDate).getTime() - new Date(a.administeredDate).getTime())
    .map(m => ({ ...m, _source: m.animalId === recordId ? "individual" : "herd_treatment" }));

  res.json({
    animal,
    herd,
    medicines,
    movements,
    calvings,
    mastitis,
    mortality: mortalityRows[0] ?? null,
    diseaseIncidents,
    stats: {
      medicineCount: medicines.length,
      movementCount: movements.length,
      calvingCount: calvings.length,
      mastitisCount: mastitis.length,
      diseaseIncidentCount: diseaseIncidents.length,
    },
  });
});

// ─── Animal Vaccination History ───────────────────────────────────────────────
// Aggregates all species-specific vaccination programme records for the herd/flock
// this animal belongs to, plus any vaccine medicine records linked directly to the animal.
router.get("/farms/:farmId/animals/:animalId/vaccination-history", requireAuth, requireTenant, requireModuleByKey("livestock-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const animalId = parseInt(req.params.animalId as string, 10);
  if (isNaN(animalId)) { res.status(400).json({ error: "Invalid animal ID" }); return; }

  const [animal] = await db.select().from(livestockAnimalsTable)
    .where(and(eq(livestockAnimalsTable.id, animalId), eq(livestockAnimalsTable.farmId, farmId)));
  if (!animal) { res.status(404).json({ error: "Animal not found" }); return; }

  const herdId = animal.herdId;
  const species = (animal.species ?? "").toLowerCase();

  // Fetch species-specific vaccination programme records for this animal's herd/flock,
  // and vaccine-type medicine records linked directly to the animal or its whole-herd treatments.
  const [sheepVacc, goatVacc, pigVacc, poultryVacc, medicineDirect, medicineHerd] = await Promise.all([
    // Sheep — flockId FK
    (species === "sheep" && herdId)
      ? db.select().from(sheepVaccinationProgrammesTable)
          .where(and(eq(sheepVaccinationProgrammesTable.farmId, farmId), eq(sheepVaccinationProgrammesTable.flockId, herdId)))
          .orderBy(desc(sheepVaccinationProgrammesTable.vaccinationDate))
      : Promise.resolve([]),
    // Goat — herdId FK
    (species === "goat" && herdId)
      ? db.select().from(goatVaccinationProgrammesTable)
          .where(and(eq(goatVaccinationProgrammesTable.farmId, farmId), eq(goatVaccinationProgrammesTable.herdId, herdId)))
          .orderBy(desc(goatVaccinationProgrammesTable.vaccinationDate))
      : Promise.resolve([]),
    // Pig — herdId FK
    (species === "pig" && herdId)
      ? db.select().from(pigVaccinationRecordsTable)
          .where(and(eq(pigVaccinationRecordsTable.farmId, farmId), eq(pigVaccinationRecordsTable.herdId, herdId)))
          .orderBy(desc(pigVaccinationRecordsTable.vaccinationDate))
      : Promise.resolve([]),
    // Poultry — flockId FK
    ((species === "chicken" || species === "turkey" || species === "duck" || species === "poultry" || species === "broiler" || species === "layer") && herdId)
      ? db.select().from(poultryVaccinationRecordsTable)
          .where(and(eq(poultryVaccinationRecordsTable.farmId, farmId), eq(poultryVaccinationRecordsTable.flockId, herdId)))
          .orderBy(desc(poultryVaccinationRecordsTable.vaccinationDate))
      : Promise.resolve([]),
    // Medicine records linked directly to this individual animal
    db.select().from(livestockMedicineRecordsTable)
      .where(and(eq(livestockMedicineRecordsTable.farmId, farmId), eq(livestockMedicineRecordsTable.animalId, animalId)))
      .orderBy(desc(livestockMedicineRecordsTable.administeredDate)),
    // Whole-herd / group medicine records for the herd (for non-species-specific lookup; cattle fall here)
    herdId
      ? db.select().from(livestockMedicineRecordsTable)
          .where(and(
            eq(livestockMedicineRecordsTable.farmId, farmId),
            eq(livestockMedicineRecordsTable.herdId, herdId),
            or(
              inArray(livestockMedicineRecordsTable.treatmentScope, ["group", "whole_herd"]),
              isNull(livestockMedicineRecordsTable.treatmentScope),
            ),
          ))
          .orderBy(desc(livestockMedicineRecordsTable.administeredDate))
      : Promise.resolve([]),
  ]);

  // Filter group-scope medicine records by ear tag where tags are specified
  const animalEarTag = (animal.earTagNumber ?? "").toLowerCase();
  const animalTagNumber = (animal.tagNumber ?? "").toLowerCase();
  const filteredMedicineHerd = (medicineHerd as any[]).filter((m: any) => {
    if (m.treatmentScope === "whole_herd" || m.treatmentScope === null) return true;
    if (m.treatmentScope === "group") {
      if (!m.treatedAnimalTags) return false;
      const tags = m.treatedAnimalTags.split(",").map((t: string) => t.trim().toLowerCase());
      return (animalEarTag && tags.includes(animalEarTag)) || (animalTagNumber && tags.includes(animalTagNumber));
    }
    return false;
  });

  // Normalise all sources into a unified shape
  const normalise = (source: string, speciesLabel: string) => (r: any) => ({
    id: r.id,
    source,
    speciesLabel,
    date: r.vaccinationDate ?? r.administeredDate,
    vaccineProduct: r.vaccineProduct ?? r.medicineName,
    vaccinationCategory: r.vaccinationCategory ?? r.reason ?? null,
    batchNumber: r.batchNumber ?? null,
    numberTreated: r.numberTreated ?? r.treatedAnimalCount ?? null,
    administeredBy: r.administeredBy ?? null,
    withdrawalPeriodDays: r.withdrawalPeriodDays ?? null,
    nextDueDate: r.nextDueDate ?? null,
    vetPrescribed: r.vetPrescribed ?? false,
    ageGroupTreated: r.ageClassTreated ?? r.ageGroupTreated ?? null,
    administrationRoute: r.administrationRoute ?? null,
    notes: r.notes ?? null,
  });

  // Merge and deduplicate medicine records
  const seenMedIds = new Set<number>();
  const allMedicineRecords = [...(medicineDirect as any[]), ...filteredMedicineHerd].filter(m => {
    if (seenMedIds.has(m.id)) return false;
    seenMedIds.add(m.id);
    return true;
  });

  const records = [
    ...(sheepVacc as any[]).map(normalise("sheep_vacc_programme", "Sheep")),
    ...(goatVacc as any[]).map(normalise("goat_vacc_programme", "Goat")),
    ...(pigVacc as any[]).map(normalise("pig_vacc_record", "Pig")),
    ...(poultryVacc as any[]).map(normalise("poultry_vacc_record", "Poultry")),
    ...allMedicineRecords.map(normalise("medicine_record", species ? species.charAt(0).toUpperCase() + species.slice(1) : "Animal")),
  ].sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));

  res.json({ records, herdId, species });
});

