// ─── Fly-Tipping Incidents ────────────────────────────────────────────────────
router.get("/farms/:farmId/fly-tipping", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const incidents = await db.select().from(flyTippingIncidentsTable).where(eq(flyTippingIncidentsTable.farmId, farmId)).orderBy(desc(flyTippingIncidentsTable.discoveredAt));
  const photos = incidents.length ? await db.select().from(flyTippingPhotosTable).where(eq(flyTippingPhotosTable.farmId, farmId)) : [];
  const photosByIncident: Record<number, typeof photos> = {};
  photos.forEach(p => { if (!photosByIncident[p.incidentId]) photosByIncident[p.incidentId] = []; photosByIncident[p.incidentId].push(p); });
  res.json({ records: incidents.map(i => ({ ...i, photos: photosByIncident[i.id] ?? [] })) });
});

router.post("/farms/:farmId/fly-tipping", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const [record] = await db.insert(flyTippingIncidentsTable).values({ ...sanitiseBody(req.body as Record<string, unknown>), farmId }).returning();
  // Fire-and-forget: SMS managers when hazardous fly-tipping is reported
  if (req.body.isHazardous === true || req.body.isHazardous === "true") {
    void (async () => {
      try {
        const [farm] = await db.select({ tenantId: farmsTable.tenantId, name: farmsTable.name }).from(farmsTable).where(eq(farmsTable.id, farmId)).limit(1);
        if (!farm) return;
        const { userTenantsTable } = await import("@workspace/db");
        const managers = await db
          .select({ phone: usersTable.phoneNumber })
          .from(userTenantsTable)
          .innerJoin(usersTable, eq(userTenantsTable.userId, usersTable.id))
          .where(and(eq(userTenantsTable.tenantId, farm.tenantId), isNotNull(usersTable.phoneNumber), ne(usersTable.smsOptIn, "none")));
        const location = String(req.body.locationDescription ?? "location not specified");
        const msg = `BDE Farm Trac [HAZARDOUS FLY-TIPPING]: Hazardous waste discovered at ${farm.name} — ${location}. Do NOT touch or move. Contact Environment Agency: 0800 80 70 60. Log in to Land Management → Fly-Tipping.`;
        const seen = new Set<string>();
        for (const m of managers) {
          if (m.phone && !seen.has(m.phone)) { seen.add(m.phone); await sendSms(m.phone, msg); }
        }
      } catch (err) { console.error("[Fly-tipping SMS]", err); }
    })();
  }
  res.json({ record });
});

