router.post("/farms/:farmId/storage-locations/:locationId/charges/auto-generate", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const locationId = parseInt(req.params.locationId as string);
  if (isNaN(locationId)) { res.status(400).json({ error: "Invalid location ID" }); return; }
  const [loc] = await db.select().from(storageLocationsTable).where(and(eq(storageLocationsTable.id, locationId), eq(storageLocationsTable.farmId, farmId)));
  if (!loc) { res.status(404).json({ error: "Location not found" }); return; }
  const { periodStart, periodEnd, quantityTonnes, chargeTypes } = req.body as {
    periodStart: string; periodEnd: string; quantityTonnes: number; chargeTypes: string[];
  };
  const startDate = new Date(periodStart);
  const endDate = new Date(periodEnd);
  const weeks = Math.max(1, Math.round((endDate.getTime() - startDate.getTime()) / (7 * 24 * 60 * 60 * 1000)));
  const lines: typeof merchantStorageChargesTable.$inferInsert[] = [];
  if (chargeTypes.includes("storage") && loc.storageRatePptWeek) {
    const rate = parseFloat(loc.storageRatePptWeek);
    lines.push({ farmId, locationId, chargeDate: periodEnd, chargeType: "storage", description: `Storage ${weeks}wk × ${quantityTonnes}t @ £${rate}/t/wk`, quantityTonnes: String(quantityTonnes), rateUsed: loc.storageRatePptWeek, amountPence: Math.round(rate * quantityTonnes * weeks * 100), isAutoGenerated: true });
  }
  if (chargeTypes.includes("intake") && loc.intakeChargePpt) {
    const rate = parseFloat(loc.intakeChargePpt);
    lines.push({ farmId, locationId, chargeDate: periodStart, chargeType: "intake", description: `Intake ${quantityTonnes}t @ £${rate}/t`, quantityTonnes: String(quantityTonnes), rateUsed: loc.intakeChargePpt, amountPence: Math.round(rate * quantityTonnes * 100), isAutoGenerated: true });
  }
  if (chargeTypes.includes("outloading") && loc.outloadingChargePpt) {
    const rate = parseFloat(loc.outloadingChargePpt);
    lines.push({ farmId, locationId, chargeDate: periodEnd, chargeType: "outloading", description: `Outloading ${quantityTonnes}t @ £${rate}/t`, quantityTonnes: String(quantityTonnes), rateUsed: loc.outloadingChargePpt, amountPence: Math.round(rate * quantityTonnes * 100), isAutoGenerated: true });
  }
  if (chargeTypes.includes("drying") && loc.dryingChargePpt) {
    const rate = parseFloat(loc.dryingChargePpt);
    lines.push({ farmId, locationId, chargeDate: periodStart, chargeType: "drying", description: `Drying ${quantityTonnes}t @ £${rate}/t`, quantityTonnes: String(quantityTonnes), rateUsed: loc.dryingChargePpt, amountPence: Math.round(rate * quantityTonnes * 100), isAutoGenerated: true });
  }
  if (chargeTypes.includes("insurance") && loc.insuranceRatePptWeek) {
    const rate = parseFloat(loc.insuranceRatePptWeek);
    lines.push({ farmId, locationId, chargeDate: periodEnd, chargeType: "insurance", description: `Insurance ${weeks}wk × ${quantityTonnes}t @ £${rate}/t/wk`, quantityTonnes: String(quantityTonnes), rateUsed: loc.insuranceRatePptWeek, amountPence: Math.round(rate * quantityTonnes * weeks * 100), isAutoGenerated: true });
  }
  if (lines.length === 0) { res.status(400).json({ error: "No applicable rates configured for selected charge types" }); return; }
  const records = await db.insert(merchantStorageChargesTable).values(lines).returning();
  res.json({ records });
});

