router.post("/farms/:farmId/planner-events", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const { title, description, eventDate, endDate, colour, estimatedDurationHours, startTime, endTime, reqTractors, reqImplements, reqVehicles, reqSprayers, reqTrailers, reqStaff, reqOther, reqOtherNotes, reqMaterials } = req.body;
  if (!title || !eventDate) { res.status(400).json({ error: "title and eventDate are required" }); return; }
  const [record] = await db.insert(farmPlannerEventsTable).values({
    farmId, title, description: description || null,
    eventDate: new Date(eventDate), endDate: endDate ? new Date(endDate) : null,
    colour: colour || "slate",
    estimatedDurationHours: estimatedDurationHours ? String(estimatedDurationHours) : null,
    startTime: startTime || null, endTime: endTime || null,
    reqTractors: Number(reqTractors) || 0, reqImplements: Number(reqImplements) || 0,
    reqVehicles: Number(reqVehicles) || 0, reqSprayers: Number(reqSprayers) || 0,
    reqTrailers: Number(reqTrailers) || 0, reqStaff: Number(reqStaff) || 0, reqOther: Number(reqOther) || 0,
    reqOtherNotes: reqOtherNotes ? JSON.stringify(reqOtherNotes) : null,
    reqMaterials: reqMaterials ? JSON.stringify(reqMaterials) : null,
  }).returning();
  res.status(201).json(record);
});

router.patch("/farms/:farmId/planner-events/:recordId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const recordId = Number(req.params.recordId);
  const { title, description, eventDate, endDate, colour, estimatedDurationHours, startTime, endTime, reqTractors, reqImplements, reqVehicles, reqSprayers, reqTrailers, reqStaff, reqOther, reqOtherNotes, reqMaterials, reqCommitted } = req.body;
  const updates: Record<string, unknown> = {};
  if (title !== undefined) updates.title = title;
  if (description !== undefined) updates.description = description;
  if (eventDate !== undefined) updates.eventDate = new Date(eventDate);
  if (endDate !== undefined) updates.endDate = endDate ? new Date(endDate) : null;
  if (colour !== undefined) updates.colour = colour;
  if (estimatedDurationHours !== undefined) updates.estimatedDurationHours = estimatedDurationHours ? String(estimatedDurationHours) : null;
  if (startTime !== undefined) updates.startTime = startTime || null;
  if (endTime !== undefined) updates.endTime = endTime || null;
  if (reqTractors !== undefined) updates.reqTractors = Number(reqTractors) || 0;
  if (reqImplements !== undefined) updates.reqImplements = Number(reqImplements) || 0;
  if (reqVehicles !== undefined) updates.reqVehicles = Number(reqVehicles) || 0;
  if (reqSprayers !== undefined) updates.reqSprayers = Number(reqSprayers) || 0;
  if (reqTrailers !== undefined) updates.reqTrailers = Number(reqTrailers) || 0;
  if (reqStaff !== undefined) updates.reqStaff = Number(reqStaff) || 0;
  if (reqOther !== undefined) updates.reqOther = Number(reqOther) || 0;
  if (reqOtherNotes !== undefined) updates.reqOtherNotes = reqOtherNotes ? JSON.stringify(reqOtherNotes) : null;
  if (reqMaterials !== undefined) updates.reqMaterials = reqMaterials ? JSON.stringify(reqMaterials) : null;
  if (reqCommitted !== undefined) {
    updates.reqCommitted = Boolean(reqCommitted);
    if (Boolean(reqCommitted)) {
      const userId = req.userId ?? "unknown";
      const [member] = await db.select({ firstName: farmMembersTable.firstName, lastName: farmMembersTable.lastName })
        .from(farmMembersTable).where(eq(farmMembersTable.linkedUserId, userId as any)).limit(1);
      updates.reqCommittedBy = member ? `${member.firstName} ${member.lastName}`.trim() : "Unknown";
      updates.reqCommittedAt = new Date();
    } else {
      updates.reqCommittedBy = null;
      updates.reqCommittedAt = null;
    }
  }
  // Actuals (Plan vs Actual / As-Built)
  const { actualDate, actualTractors, actualImplements, actualVehicles, actualSprayers, actualTrailers, actualStaff, actualMaterials, actualNotes, actualStatus, clearActuals } = req.body;
  if (clearActuals) {
    updates.actualDate = null; updates.actualTractors = 0; updates.actualImplements = 0;
    updates.actualVehicles = 0; updates.actualSprayers = 0; updates.actualTrailers = 0;
    updates.actualStaff = 0; updates.actualMaterials = null; updates.actualNotes = null;
    updates.actualStatus = null; updates.actualCompletedAt = null; updates.actualCompletedBy = null;
  } else if (actualStatus !== undefined) {
    if (actualDate !== undefined) updates.actualDate = actualDate || null;
    if (actualTractors !== undefined) updates.actualTractors = Number(actualTractors) || 0;
    if (actualImplements !== undefined) updates.actualImplements = Number(actualImplements) || 0;
    if (actualVehicles !== undefined) updates.actualVehicles = Number(actualVehicles) || 0;
    if (actualSprayers !== undefined) updates.actualSprayers = Number(actualSprayers) || 0;
    if (actualTrailers !== undefined) updates.actualTrailers = Number(actualTrailers) || 0;
    if (actualStaff !== undefined) updates.actualStaff = Number(actualStaff) || 0;
    if (actualMaterials !== undefined) updates.actualMaterials = actualMaterials ? JSON.stringify(actualMaterials) : null;
    if (actualNotes !== undefined) updates.actualNotes = actualNotes || null;
    updates.actualStatus = actualStatus;
    updates.actualCompletedAt = new Date();
    const userId = req.userId ?? "unknown";
    const [member] = await db.select({ firstName: farmMembersTable.firstName, lastName: farmMembersTable.lastName })
      .from(farmMembersTable).where(eq(farmMembersTable.linkedUserId, userId as any)).limit(1);
    updates.actualCompletedBy = member ? `${member.firstName} ${member.lastName}`.trim() : "Unknown";
  }
  const [record] = await db.update(farmPlannerEventsTable).set(updates).where(and(eq(farmPlannerEventsTable.id, recordId), eq(farmPlannerEventsTable.farmId, farmId))).returning();
  if (!record) { res.status(404).json({ error: "Not found" }); return; }
  res.json(record);
});

