// ─── Grain Store Cleaning Status ────────────────────────────────────────────
  router.get("/farms/:farmId/grain-storage-bins/:binId/cleaning-status", requireAuth, requireTenant, requireModuleByKey("field-crop-management", "read"), async (req: Request, res: Response): Promise<void> => {
    const farmId = await validateFarmAccess(req, res);
    if (!farmId) return;
    const binId = parseInt(req.params.binId as string);
    if (isNaN(binId)) { res.status(400).json({ error: "Invalid binId" }); return; }

    const [lastCleaning] = await db.select()
      .from(cleaningDisinfectionRecordsTable)
      .where(and(eq(cleaningDisinfectionRecordsTable.farmId, farmId), eq(cleaningDisinfectionRecordsTable.locationId, binId)))
      .orderBy(desc(cleaningDisinfectionRecordsTable.cleanedDate))
      .limit(1);

    const [lastDispatch] = await db.select()
      .from(cropStockMovementsTable)
      .where(and(eq(cropStockMovementsTable.farmId, farmId), eq(cropStockMovementsTable.binId, binId), eq(cropStockMovementsTable.direction, "out")))
      .orderBy(desc(cropStockMovementsTable.movedAt))
      .limit(1);

    const [level] = await db.select()
      .from(cropStockLevelsTable)
      .where(and(eq(cropStockLevelsTable.farmId, farmId), eq(cropStockLevelsTable.binId, binId)))
      .limit(1);

    const currentTonnes = parseFloat(level?.quantityTonnes ?? "0");
    const isEmpty = currentTonnes <= 0;
    const cleanedAfterDispatch = lastCleaning && lastDispatch
      ? new Date(lastCleaning.cleanedDate) >= new Date(lastDispatch.movedAt ?? 0)
      : !!lastCleaning;

    res.json({
      lastCleaning: lastCleaning ?? null,
      lastDispatch: lastDispatch ?? null,
      currentTonnes,
      isEmpty,
      cleanedAfterDispatch,
      requiresCleaningLog: isEmpty && !cleanedAfterDispatch,
    });
  });

  // ─── Equipment Defect Reports Register ───────────────
router.get("/farms/:farmId/equipment-defect-reports", requireAuth, requireTenant, requireModuleByKey("equipment-management", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const records = await db.select().from(equipmentDefectReportsTable).where(eq(equipmentDefectReportsTable.farmId, farmId)).orderBy(desc(equipmentDefectReportsTable.reportedDate));
  res.json({ records });
});

router.post("/farms/:farmId/equipment-defect-reports", requireAuth, requireTenant, requireModuleByKey("equipment-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const { mobileId } = req.body;
  if (mobileId) {
    const [existing] = await db.select({ id: equipmentDefectReportsTable.id }).from(equipmentDefectReportsTable).where(and(eq(equipmentDefectReportsTable.farmId, farmId), eq(equipmentDefectReportsTable.mobileId, mobileId))).limit(1);
    if (existing) { res.json({ record: existing, duplicate: true }); return; }
  }
  const year = new Date().getFullYear();
  const [countRow] = await db.select({ count: db.$count(equipmentDefectReportsTable.id) }).from(equipmentDefectReportsTable).where(and(eq(equipmentDefectReportsTable.farmId, farmId)));
  const seq = (Number(countRow?.count ?? 0) + 1).toString().padStart(4, "0");
  const defectRef = req.body.defectRef || `ED-${year}-${seq}`;
  const reportedDate = req.body.reportedDate || req.body.reportedDate || new Date().toISOString();
  const equipmentName = req.body.equipmentName || req.body.equipmentName || "Unknown";
  const defectDescription = req.body.defectDescription || req.body.defectDescription || "";
  const [record] = await db.insert(equipmentDefectReportsTable).values({ ...sanitiseBody(req.body as Record<string, unknown>), farmId, defectRef, reportedDate: new Date(reportedDate), equipmentName, defectDescription }).returning();
  // Fire-and-forget: SMS managers when a high or critical severity defect is reported
  const sev = String(req.body.severity ?? "");
  if (sev === "high" || sev === "critical") {
    void (async () => {
      try {
        const [farm] = await db.select({ tenantId: farmsTable.tenantId, name: farmsTable.name }).from(farmsTable).where(eq(farmsTable.id, farmId)).limit(1);
        if (!farm) return;
        const { userTenantsTable } = await import("@workspace/db");
        const managers = await db
          .select({ phone: usersTable.phoneNumber })
          .from(userTenantsTable)
          .innerJoin(usersTable, eq(userTenantsTable.userId, usersTable.id))
          .where(and(eq(userTenantsTable.tenantId, farm.tenantId), isNotNull(usersTable.phoneNumber), ne(usersTable.smsOptIn, "none")));
        const reporter = String(req.body.reportedBy ?? "A team member");
        const sevLabel = sev === "critical" ? "CRITICAL" : "High";
        const msg = `BDE Farm Trac [${sevLabel} DEFECT]: ${reporter} has reported a ${sevLabel.toLowerCase()} severity defect on ${equipmentName} at ${farm.name}. Ref: ${defectRef}. Review in Equipment → Defect Reports.`;
        const seen = new Set<string>();
        for (const m of managers) {
          if (m.phone && !seen.has(m.phone)) { seen.add(m.phone); await sendSms(m.phone, msg); }
        }
      } catch (err) { console.error("[Equipment Defect SMS]", err); }
    })();
  }
  res.status(201).json({ record });
});

router.patch("/farms/:farmId/equipment-defect-reports/:recordId/status", requireAuth, requireTenant, requireModuleByKey("equipment-management", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const recordId = getRecordId(req);
  if (!recordId) { res.status(400).json({ error: "Invalid ID" }); return; }
  const { status, resolvedBy } = req.body;
  const updates: Record<string, unknown> = { status };
  if (status === "resolved" || status === "closed") { updates.resolvedDate = new Date(); if (resolvedBy) updates.resolvedBy = resolvedBy; }
  const [record] = await db.update(equipmentDefectReportsTable).set(updates).where(and(eq(equipmentDefectReportsTable.id, recordId), eq(equipmentDefectReportsTable.farmId, farmId))).returning();
  res.json({ record });
});

