// List all farm members (staff records) for a farm — includes department name join
router.get("/farms/:farmId/members", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const rows = await db
    .select({
      id: farmMembersTable.id,
      farmId: farmMembersTable.farmId,
      tenantId: farmMembersTable.tenantId,
      linkedUserId: farmMembersTable.linkedUserId,
      firstName: farmMembersTable.firstName,
      lastName: farmMembersTable.lastName,
      email: farmMembersTable.email,
      phone: farmMembersTable.phone,
      jobTitle: farmMembersTable.jobTitle,
      departmentId: farmMembersTable.departmentId,
      departmentName: farmDepartmentsTable.name,
      departmentColour: farmDepartmentsTable.colour,
      employedFrom: farmMembersTable.employedFrom,
      employedTo: farmMembersTable.employedTo,
      farmRole: farmMembersTable.farmRole,
      accessType: farmMembersTable.accessType,
      invitationStatus: farmMembersTable.invitationStatus,
      isActive: farmMembersTable.isActive,
      notes: farmMembersTable.notes,
      niNumber: farmMembersTable.niNumber,
      payrollNumber: farmMembersTable.payrollNumber,
      nokName: farmMembersTable.nokName,
      nokRelationship: farmMembersTable.nokRelationship,
      nokPhone: farmMembersTable.nokPhone,
      nokEmail: farmMembersTable.nokEmail,
      createdAt: farmMembersTable.createdAt,
      updatedAt: farmMembersTable.updatedAt,
    })
    .from(farmMembersTable)
    .leftJoin(farmDepartmentsTable, eq(farmMembersTable.departmentId, farmDepartmentsTable.id))
    .where(eq(farmMembersTable.farmId, farmId))
    .orderBy(farmMembersTable.lastName, farmMembersTable.firstName);

  // Fetch secondary department memberships for all returned members in one query
  const memberIds = rows.map(r => r.id);
  const secondaryRows = memberIds.length > 0
    ? await db.select({
        memberId: staffDepartmentMembershipsTable.memberId,
        id: farmDepartmentsTable.id,
        name: farmDepartmentsTable.name,
        colour: farmDepartmentsTable.colour,
      })
      .from(staffDepartmentMembershipsTable)
      .innerJoin(farmDepartmentsTable, eq(staffDepartmentMembershipsTable.departmentId, farmDepartmentsTable.id))
      .where(inArray(staffDepartmentMembershipsTable.memberId, memberIds))
    : [];
  const secondaryByMember = new Map<number, { id: number; name: string; colour: string }[]>();
  secondaryRows.forEach(sr => {
    if (!secondaryByMember.has(sr.memberId)) secondaryByMember.set(sr.memberId, []);
    secondaryByMember.get(sr.memberId)!.push({ id: sr.id, name: sr.name, colour: sr.colour });
  });
  const members = rows.map(r => ({ ...r, secondaryDepartments: secondaryByMember.get(r.id) ?? [] }));
  res.json({ members });
});

// Create a staff record (no system access by default)
router.post("/farms/:farmId/members", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const tenantId = (req as any).tenantId as number;
  const { firstName, lastName, email, phone, jobTitle, departmentId, secondaryDepartmentIds, farmRole, employedFrom, employedTo, notes, niNumber, payrollNumber, nokName, nokRelationship, nokPhone, nokEmail } = req.body;
  if (!firstName || !lastName) { res.status(400).json({ error: "First name and last name are required" }); return; }
  const [member] = await db.insert(farmMembersTable).values({
    farmId,
    tenantId,
    firstName,
    lastName,
    email: email ?? null,
    phone: phone ?? null,
    jobTitle: jobTitle ?? null,
    departmentId: departmentId ? Number(departmentId) : null,
    farmRole: farmRole ?? "operator",
    accessType: "none",
    invitationStatus: "not_invited",
    employedFrom: employedFrom ? new Date(employedFrom) : null,
    employedTo: employedTo ? new Date(employedTo) : null,
    notes: notes ?? null,
    niNumber: niNumber ?? null,
    payrollNumber: payrollNumber ?? null,
    nokName: nokName ?? null,
    nokRelationship: nokRelationship ?? null,
    nokPhone: nokPhone ?? null,
    nokEmail: nokEmail ?? null,
  }).returning();
  // Insert secondary department memberships
  if (Array.isArray(secondaryDepartmentIds) && secondaryDepartmentIds.length > 0) {
    await db.insert(staffDepartmentMembershipsTable).values(
      secondaryDepartmentIds.map((deptId: number) => ({ memberId: member.id, departmentId: Number(deptId) }))
    ).onConflictDoNothing();
  }
  res.status(201).json({ member });
});

// Update a farm member record
router.put("/farms/:farmId/members/:memberId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const memberId = parseInt(req.params.memberId as string);
  const { firstName, lastName, email, phone, jobTitle, departmentId, secondaryDepartmentIds, farmRole, accessType, employedFrom, employedTo, isActive, notes, niNumber, payrollNumber, nokName, nokRelationship, nokPhone, nokEmail } = req.body;
  const [member] = await db.update(farmMembersTable).set({
    ...(firstName !== undefined && { firstName }),
    ...(lastName !== undefined && { lastName }),
    ...(email !== undefined && { email }),
    ...(phone !== undefined && { phone }),
    ...(jobTitle !== undefined && { jobTitle }),
    ...(departmentId !== undefined && { departmentId: departmentId ? Number(departmentId) : null }),
    ...(farmRole !== undefined && { farmRole }),
    ...(accessType !== undefined && { accessType }),
    ...(employedFrom !== undefined && { employedFrom: employedFrom ? new Date(employedFrom) : null }),
    ...(employedTo !== undefined && { employedTo: employedTo ? new Date(employedTo) : null }),
    ...(isActive !== undefined && { isActive }),
    ...(notes !== undefined && { notes }),
    ...(niNumber !== undefined && { niNumber }),
    ...(payrollNumber !== undefined && { payrollNumber }),
    ...(nokName !== undefined && { nokName }),
    ...(nokRelationship !== undefined && { nokRelationship }),
    ...(nokPhone !== undefined && { nokPhone }),
    ...(nokEmail !== undefined && { nokEmail }),
  }).where(and(eq(farmMembersTable.id, memberId), eq(farmMembersTable.farmId, farmId))).returning();
  if (!member) { res.status(404).json({ error: "Member not found" }); return; }
  // Replace secondary department memberships if provided
  if (Array.isArray(secondaryDepartmentIds)) {
    await db.delete(staffDepartmentMembershipsTable).where(eq(staffDepartmentMembershipsTable.memberId, memberId));
    if (secondaryDepartmentIds.length > 0) {
      await db.insert(staffDepartmentMembershipsTable).values(
        secondaryDepartmentIds.map((deptId: number) => ({ memberId, departmentId: Number(deptId) }))
      ).onConflictDoNothing();
    }
  }
  res.json({ member });
});

