// ─── What3Words Proxy ─────────────────────────────────────────────────────────
router.get("/utils/w3w-convert", requireAuth, async (req: Request, res: Response): Promise<void> => {
  const { lat, lng } = req.query as { lat?: string; lng?: string };
  if (!lat || !lng) { res.status(400).json({ error: "lat and lng are required" }); return; }
  const apiKey = process.env.W3W_API_KEY;
  if (!apiKey) { res.status(503).json({ error: "W3W_API_KEY not configured", noKey: true }); return; }
  try {
    const url = `https://api.what3words.com/v3/convert-to-3wa?coordinates=${encodeURIComponent(lat + "," + lng)}&language=en&format=json&key=${apiKey}`;
    const r = await fetch(url);
    const data = await r.json() as any;
    if (data.error) { res.status(400).json({ error: data.error.message ?? "W3W API error" }); return; }
    res.json({ words: data.words, nearestPlace: data.nearestPlace, country: data.country });
  } catch (e) {
    res.status(500).json({ error: "Failed to contact W3W API" });
  }
});

// ─── Accident Book ────────────────────────────────────────────────────────────
router.get("/farms/:farmId/accident-book", requireAuth, requireTenant, requireModuleByKey("risk-waste", "read"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const records = await db.select().from(accidentBookTable).where(eq(accidentBookTable.farmId, farmId)).orderBy(desc(accidentBookTable.incidentDate));
  const photos = await db.select().from(accidentBookPhotosTable).where(eq(accidentBookPhotosTable.farmId, farmId));
  const photosByRecord: Record<number, typeof photos> = {};
  for (const p of photos) { if (!photosByRecord[p.recordId]) photosByRecord[p.recordId] = []; photosByRecord[p.recordId].push(p); }
  res.json({ records: records.map(r => ({ ...r, photos: photosByRecord[r.id] ?? [] })) });
});

router.post("/farms/:farmId/accident-book", requireAuth, requireTenant, requireModuleByKey("risk-waste", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const [record] = await db.insert(accidentBookTable).values({ ...sanitiseBody(req.body as Record<string, unknown>), farmId }).returning();
  res.status(201).json({ record });
  const isRiddor = req.body.riddorReportable === true || req.body.riddorReportable === "true";
  if (isRiddor) {
    void (async () => {
      try {
        const [farm] = await db.select({ tenantId: farmsTable.tenantId, name: farmsTable.name }).from(farmsTable).where(eq(farmsTable.id, farmId)).limit(1);
        if (!farm) return;
        const { userTenantsTable } = await import("@workspace/db");
        const managers = await db
          .select({ phone: usersTable.phoneNumber })
          .from(userTenantsTable)
          .innerJoin(usersTable, eq(userTenantsTable.userId, usersTable.id))
          .where(and(eq(userTenantsTable.tenantId, farm.tenantId), isNotNull(usersTable.phoneNumber), ne(usersTable.smsOptIn, "none")));
        const personName = String(req.body.personName ?? "A person");
        const location = String(req.body.incidentLocation ?? "location not specified");
        const riddorCat = req.body.riddorCategory ? ` Category: ${String(req.body.riddorCategory).substring(0, 80)}.` : "";
        const msg = `BDE Farm Trac [RIDDOR ACCIDENT]: A RIDDOR-reportable incident involving ${personName} has been logged at ${farm.name} (${location}).${riddorCat} Report to HSE at riddor.hse.gov.uk. Review in H&S → Accident Book.`;
        const seen = new Set<string>();
        for (const m of managers) {
          if (m.phone && !seen.has(m.phone)) { seen.add(m.phone); await sendSms(m.phone, msg); }
        }
        await createRiddorNotification({ tenantId: farm.tenantId, farmId, recordId: record.id, personName, incidentLocation: location, riddorCategory: req.body.riddorCategory ? String(req.body.riddorCategory) : null });
      } catch { /* fire-and-forget */ }
    })();
  }
});

router.put("/farms/:farmId/accident-book/:recordId", requireAuth, requireTenant, requireModuleByKey("risk-waste", "write"), async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const recordId = getRecordId(req);
  if (!recordId) { res.status(400).json({ error: "Invalid ID" }); return; }
  const [record] = await db.update(accidentBookTable).set(sanitiseBody(req.body as Record<string, unknown>)).where(and(eq(accidentBookTable.id, recordId), eq(accidentBookTable.farmId, farmId))).returning();
  res.json({ record });
  if ((req.body.riddorReportable === true || req.body.riddorReportable === "true") && record) {
    void (async () => {
      try {
        const [farm] = await db.select({ tenantId: farmsTable.tenantId }).from(farmsTable).where(eq(farmsTable.id, farmId)).limit(1);
        if (farm) await createRiddorNotification({ tenantId: farm.tenantId, farmId, recordId: record.id, personName: String(req.body.personName ?? "A person"), incidentLocation: String(req.body.incidentLocation ?? "location not specified"), riddorCategory: req.body.riddorCategory ? String(req.body.riddorCategory) : null });
      } catch { /* fire-and-forget */ }
    })();
  }
});

