// POST submit a movement to CTWS
router.post("/farms/:farmId/bcms-submit/:movementId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const movementId = parseInt(req.params.movementId as string);

  const [movement] = await db.select().from(livestockMovementsTable).where(and(eq(livestockMovementsTable.id, movementId), eq(livestockMovementsTable.farmId, farmId)));
  if (!movement) { res.status(404).json({ error: "Movement not found" }); return; }

  const [creds] = await db.select().from(bcmsFarmCredentialsTable).where(eq(bcmsFarmCredentialsTable.farmId, farmId));
  if (!creds?.isConfigured) { res.status(400).json({ error: "BCMS credentials not configured. Go to Farm Settings → BCMS / CTS Integration to set up your credentials." }); return; }

  const password = decryptCredential(creds.ctwsPasswordEncrypted ?? "");
  const typeMap: Record<string, "movement_on" | "movement_off" | "birth" | "death"> = { on: "movement_on", off: "movement_off", birth: "birth", death: "death" };
  const submissionType = typeMap[movement.movementType] ?? "movement_on";

  const movDate = movement.movementDate ? new Date(movement.movementDate).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);

  const [submission] = await db.insert(bcmsSubmissionsTable).values({
    farmId, movementId, submissionType, status: "pending",
    sandboxMode: isSandboxMode(), submittedAt: new Date(),
  }).returning();

  try {
    const result = await submitMovement({
      ctwsUsername: creds.ctwsUsername!,
      ctwsPassword: password,
      holdingNumber: creds.holdingNumber!,
      movementType: submissionType,
      movementDate: movDate,
      numberOfAnimals: movement.numberOfAnimals ?? 1,
      earTagNumbers: movement.earTagNumbers ?? undefined,
      fromLocation: movement.fromLocation ?? creds.holdingNumber!,
      toLocation: movement.toLocation ?? creds.holdingNumber!,
      licenceNumber: movement.licenceNumber ?? undefined,
      species: movement.species ?? undefined,
    });

    const status = result.success ? "submitted" : "failed";
    await db.update(bcmsSubmissionsTable).set({
      status, sandboxMode: result.sandbox,
      bcmsReference: result.reference, errorMessage: result.errorMessage,
      xmlPayload: result.xmlPayload, responsePayload: result.responseXml,
      acknowledgedAt: result.success ? new Date() : undefined,
    }).where(eq(bcmsSubmissionsTable.id, submission.id));

    if (result.success) {
      await db.update(livestockMovementsTable).set({
        legalNotificationSubmitted: true,
        legalNotificationDate: new Date(),
        bcmsSubmissionRef: result.reference ?? `SANDBOX-${submission.id}`,
      }).where(eq(livestockMovementsTable.id, movementId));
    }

    res.json({ success: result.success, sandbox: result.sandbox, reference: result.reference, error: result.errorMessage });
  } catch (err: any) {
    await db.update(bcmsSubmissionsTable).set({ status: "failed", errorMessage: err?.message ?? "Unknown error" }).where(eq(bcmsSubmissionsTable.id, submission.id));
    res.status(500).json({ error: err?.message ?? "Submission failed" });
  }
});

// ─── LIS / Livestock Information Service ──────────────────────────────────────

// GET connection status (never returns raw password or access token)
router.get("/farms/:farmId/lis-credentials", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const [token] = await db.select().from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));
  if (!token) {
    res.json({ configured: false, sandboxMode: isLisSandboxMode(), subscriptionKeyConfigured: !isLisSandboxMode() });
    return;
  }
  res.json({
    configured: token.isConfigured,
    sandboxMode: isLisSandboxMode(),
    subscriptionKeyConfigured: !isLisSandboxMode(),
    lisUsername: token.lisUsername,
    lastTestedAt: token.lastTestedAt,
    testStatus: token.testStatus,
    testMessage: token.testMessage,
    tokenExpiresAt: token.tokenExpiresAt,
    lisLastSyncedAt: token.lisLastSyncedAt,
    lisLastSyncSummary: token.lisLastSyncSummary,
    lisSyncHistory: token.lisSyncHistory,
  });
});

// PUT save credentials
router.put("/farms/:farmId/lis-credentials", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const { lisUsername, lisPassword } = req.body as { lisUsername?: string; lisPassword?: string };
  const [existing] = await db.select().from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));
  const passwordToStore = lisPassword ? encryptCredential(lisPassword) : existing?.lisPasswordEncrypted;
  const data = {
    lisUsername: lisUsername ?? existing?.lisUsername,
    lisPasswordEncrypted: passwordToStore,
    isConfigured: !!(lisUsername || existing?.lisUsername) && !!passwordToStore,
    sandboxMode: isLisSandboxMode(),
    updatedAt: new Date(),
  };
  let record;
  if (existing) {
    [record] = await db.update(lisFarmTokensTable).set(data).where(eq(lisFarmTokensTable.farmId, farmId)).returning();
  } else {
    [record] = await db.insert(lisFarmTokensTable).values({ ...data, farmId }).returning();
  }
  res.json({ success: true, configured: record.isConfigured });
});

// DELETE credentials
router.delete("/farms/:farmId/lis-credentials", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  await db.delete(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));
  res.json({ success: true });
});

// POST test connection — authenticates with Azure B2C and updates stored token
router.post("/farms/:farmId/lis-credentials/test", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const [creds] = await db.select().from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));
  if (!creds?.isConfigured) {
    res.status(400).json({ success: false, message: "LIS not connected. Click 'Sign in with LIS' to authenticate." });
    return;
  }

  // ── Try OAuth token (primary path) ──────────────────────────────────────────
  let token = creds.accessToken ?? undefined;
  const tokenExpired = !token || (creds.tokenExpiresAt && new Date(creds.tokenExpiresAt) < new Date(Date.now() + 60_000));

  if (tokenExpired && creds.refreshToken) {
    const refreshResult = await refreshLisToken(creds.refreshToken);
    if (refreshResult.success && refreshResult.accessToken) {
      token = refreshResult.accessToken;
      await db.update(lisFarmTokensTable).set({
        accessToken: refreshResult.accessToken,
        refreshToken: refreshResult.refreshToken ?? undefined,
        tokenExpiresAt: refreshResult.expiresIn ? new Date(Date.now() + refreshResult.expiresIn * 1000) : undefined,
        updatedAt: new Date(),
      }).where(eq(lisFarmTokensTable.farmId, farmId));
    } else {
      token = undefined;
    }
  }

  // ── Legacy ROPC fallback (for farms migrated from the old credential form) ──
  // Skip ROPC if this farm has a refresh token — it's an OAuth farm and ROPC is blocked
  if (!token && creds.lisPasswordEncrypted && !creds.refreshToken) {
    const password = decryptCredential(creds.lisPasswordEncrypted);
    const result = await testLisConnection(creds.lisUsername!, password);
    await db.update(lisFarmTokensTable).set({
      testStatus: result.success ? "ok" : "failed",
      testMessage: result.success
        ? (result.sandbox ? "Sandbox test passed (ROPC legacy)" : "Connected via ROPC — consider re-connecting via LIS sign-in")
        : (result.errorMessage ?? "Connection failed"),
      lastTestedAt: new Date(),
      ...(result.accessToken && { accessToken: result.accessToken, refreshToken: result.refreshToken ?? undefined, tokenExpiresAt: result.tokenExpiresAt ?? undefined }),
      updatedAt: new Date(),
    }).where(eq(lisFarmTokensTable.farmId, farmId));
    res.json({ success: result.success, sandbox: result.sandbox, message: result.errorMessage ?? (result.success ? "OK" : "Failed") });
    return;
  }

  if (!token) {
    // No usable token at all — tell them to re-connect
    await db.update(lisFarmTokensTable).set({ testStatus: "failed", testMessage: "Token expired — please sign in again", lastTestedAt: new Date(), updatedAt: new Date() }).where(eq(lisFarmTokensTable.farmId, farmId));
    res.status(401).json({ success: false, message: "LIS token has expired. Please click 'Sign in with LIS' to reconnect." });
    return;
  }

  // Token is valid — call Hello World / basic API check
  if (isLisSandboxMode()) {
    await db.update(lisFarmTokensTable).set({ testStatus: "ok", testMessage: "Sandbox test passed — token valid", lastTestedAt: new Date(), updatedAt: new Date() }).where(eq(lisFarmTokensTable.farmId, farmId));
    res.json({ success: true, sandbox: true, message: "Sandbox test passed — token valid" });
    return;
  }

  const testResult = await callLisApi(token, "/hello");
  const ok = testResult.ok || testResult.status === 404; // 404 on /hello still means auth worked
  const msg = ok ? "Connected to LIS — token verified" : `LIS API returned HTTP ${testResult.status}`;
  await db.update(lisFarmTokensTable).set({ testStatus: ok ? "ok" : "failed", testMessage: msg, lastTestedAt: new Date(), updatedAt: new Date() }).where(eq(lisFarmTokensTable.farmId, farmId));
  res.json({ success: ok, sandbox: false, message: msg });
});

// GET submission history
router.get("/farms/:farmId/lis-submissions", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const submissions = await db
    .select({
      id: lisSubmissionsTable.id,
      movementId: lisSubmissionsTable.movementId,
      submissionType: lisSubmissionsTable.submissionType,
      species: lisSubmissionsTable.species,
      status: lisSubmissionsTable.status,
      sandboxMode: lisSubmissionsTable.sandboxMode,
      lisReference: lisSubmissionsTable.lisReference,
      errorMessage: lisSubmissionsTable.errorMessage,
      submittedAt: lisSubmissionsTable.submittedAt,
      acknowledgedAt: lisSubmissionsTable.acknowledgedAt,
      movementDate: livestockMovementsTable.movementDate,
      movementType: livestockMovementsTable.movementType,
      numberOfAnimals: livestockMovementsTable.numberOfAnimals,
      fromLocation: livestockMovementsTable.fromLocation,
      toLocation: livestockMovementsTable.toLocation,
    })
    .from(lisSubmissionsTable)
    .leftJoin(livestockMovementsTable, eq(lisSubmissionsTable.movementId, livestockMovementsTable.id))
    .where(eq(lisSubmissionsTable.farmId, farmId))
    .orderBy(desc(lisSubmissionsTable.submittedAt))
    .limit(200);
  res.json({ submissions });
});

// POST submit a movement to LIS
router.post("/farms/:farmId/lis-submit/:movementId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const movementId = parseInt(req.params.movementId as string);

  const [movement] = await db.select().from(livestockMovementsTable).where(and(eq(livestockMovementsTable.id, movementId), eq(livestockMovementsTable.farmId, farmId)));
  if (!movement) { res.status(404).json({ error: "Movement not found" }); return; }

  // Prevent duplicate submissions — if already successfully submitted, reject with 409
  if (movement.legalNotificationSubmitted) {
    res.status(409).json({ error: `This movement has already been successfully submitted to LIS (ref: ${movement.bcmsSubmissionRef ?? "unknown"}). Use the Undo option on the movement record if a correction is needed.` });
    return;
  }

  const species = (movement.species ?? "").toLowerCase();
  const lisSpecies = species.includes("goat") ? "GOAT" : species.includes("deer") ? "DEER" : "SHEEP";

  const [creds] = await db.select().from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));

  const typeMap: Record<string, "movement_on" | "movement_off" | "birth" | "death"> = {
    on: "movement_on", off: "movement_off", birth: "birth", death: "death",
  };
  const submissionType = typeMap[movement.movementType] ?? "movement_off";
  const movDate = movement.movementDate ? new Date(movement.movementDate).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);

  // ── Births and deaths are NOT supported in LIS CLA v1.0 ──────────────────────
  // Confirmed by LIS Development Hub Support (July 2026):
  // "Per the published public CLA v1.0 contract, births and deaths are unsupported.
  //  The public API is limited to livestock movements: transfer, transfer correction,
  //  movement review/confirmation, and undo."
  // Sheep/goat/deer births and deaths must be registered directly on the LIS keeper
  // portal at www.livestockinformation.org.uk — no API route exists in the public contract.
  if (submissionType === "birth" || submissionType === "death") {
    const eventLabel = submissionType === "birth" ? "Birth" : "Death";
    res.status(422).json({
      error: `${eventLabel} registration is not supported by the LIS CLA v1.0 public API. `
        + `Only on/off-farm livestock movements (transfers) can be submitted via CLA. `
        + `Please register this ${eventLabel.toLowerCase()} directly on the LIS keeper portal at www.livestockinformation.org.uk.`,
      unsupported: true,
    });
    return;
  }

  const password = creds?.lisPasswordEncrypted ? decryptCredential(creds.lisPasswordEncrypted) : "";

  // Refresh token if expired or not present
  let accessToken = creds?.accessToken ?? undefined;
  if (!isLisSandboxMode() && creds?.isConfigured) {
    const tokenExpired = !accessToken || (creds.tokenExpiresAt && new Date(creds.tokenExpiresAt) < new Date(Date.now() + 60_000));
    if (tokenExpired) {
      // ── Try OAuth refresh token first ───────────────────────────────────
      if (creds.refreshToken) {
        const refreshResult = await refreshLisToken(creds.refreshToken);
        if (refreshResult.success && refreshResult.accessToken) {
          accessToken = refreshResult.accessToken;
          await db.update(lisFarmTokensTable).set({
            accessToken,
            refreshToken: refreshResult.refreshToken ?? undefined,
            tokenExpiresAt: refreshResult.expiresIn ? new Date(Date.now() + refreshResult.expiresIn * 1000) : undefined,
            updatedAt: new Date(),
          }).where(eq(lisFarmTokensTable.farmId, farmId));
        } else {
          accessToken = undefined;
        }
      }
      // ── Legacy ROPC fallback ─────────────────────────────────────────────
      if (!accessToken && creds.lisPasswordEncrypted) {
        const tokenResult = await fetchLisToken(creds.lisUsername!, password);
        if (tokenResult.success && tokenResult.accessToken) {
          accessToken = tokenResult.accessToken;
          await db.update(lisFarmTokensTable).set({
            accessToken: tokenResult.accessToken,
            refreshToken: tokenResult.refreshToken ?? undefined,
            tokenExpiresAt: tokenResult.expiresIn ? new Date(Date.now() + tokenResult.expiresIn * 1000) : undefined,
            updatedAt: new Date(),
          }).where(eq(lisFarmTokensTable.farmId, farmId));
        }
      }
    }
  }

  const [submission] = await db.insert(lisSubmissionsTable).values({
    farmId,
    movementId,
    submissionType,
    species: lisSpecies,
    status: "pending",
    sandboxMode: isLisSandboxMode(),
    submittedAt: new Date(),
  }).returning();

  try {
    // ── CLA v1.0: only on/off movements reach here ────────────────────────────
    // Births and deaths are blocked by the early-return guard above.
    // Movements → POST /TransferRequests (OData endpoint).

    // ── Submission with 401 auto-retry ────────────────────────────────────────
    // On a first-attempt 401 from LIS, refresh the token once and retry.
    let result!: LisResult;

    for (let attempt = 0; attempt < 2; attempt++) {
      result = await submitLisMovement({
        lisUsername: creds?.lisUsername ?? "",
        lisPassword: password,
        accessToken,
        movementType: submissionType,
        movementDate: movDate,
        species: lisSpecies,
        numberOfAnimals: movement.numberOfAnimals ?? 1,
        departureCph: movement.fromLocation ?? undefined,
        destinationCph: movement.toLocation ?? undefined,
        earTagNumbers: movement.earTagNumbers ?? undefined,
        licenceNumber: movement.licenceNumber ?? undefined,
        fromLocation: movement.fromLocation ?? undefined,
        toLocation: movement.toLocation ?? undefined,
      });

      // On first attempt: if LIS returned 401/auth-error, refresh token and retry once
      if (attempt === 0 && !result.success && !isLisSandboxMode() && creds?.refreshToken) {
        const indicates401 = /401|Unauthorized|token.*expired|invalid.*token|AADSTS/i.test(
          (result.errorMessage ?? "") + (result.responsePayload ?? "")
        );
        if (indicates401) {
          const retryRefresh = await refreshLisToken(creds.refreshToken);
          if (retryRefresh.success && retryRefresh.accessToken) {
            accessToken = retryRefresh.accessToken;
            await db.update(lisFarmTokensTable).set({
              accessToken,
              refreshToken: retryRefresh.refreshToken ?? undefined,
              tokenExpiresAt: retryRefresh.expiresIn ? new Date(Date.now() + retryRefresh.expiresIn * 1000) : undefined,
              updatedAt: new Date(),
            }).where(eq(lisFarmTokensTable.farmId, farmId));
            continue; // retry with fresh token
          }
        }
      }
      break; // success, non-401 failure, or no refresh token available
    }

    const status = result.success ? "submitted" : "failed";
    await db.update(lisSubmissionsTable).set({
      status,
      sandboxMode: result.sandbox,
      lisReference: result.reference,
      errorMessage: result.errorMessage,
      requestPayload: result.requestPayload,
      responsePayload: result.responsePayload,
      acknowledgedAt: result.success ? new Date() : undefined,
      updatedAt: new Date(),
    }).where(eq(lisSubmissionsTable.id, submission.id));

    if (result.success) {
      await db.update(livestockMovementsTable).set({
        legalNotificationSubmitted: true,
        legalNotificationDate: new Date(),
        bcmsSubmissionRef: result.reference ?? `LIS-SANDBOX-${submission.id}`,
      }).where(eq(livestockMovementsTable.id, movementId));
    }

    res.json({ success: result.success, sandbox: result.sandbox, reference: result.reference, error: result.errorMessage });
  } catch (err: any) {
    await db.update(lisSubmissionsTable).set({ status: "failed", errorMessage: err?.message ?? "Unknown error", updatedAt: new Date() }).where(eq(lisSubmissionsTable.id, submission.id));
    res.status(500).json({ error: err?.message ?? "Submission failed" });
  }
});

// ─── LIS LIP — Cattle Submission Routes ──────────────────────────────────────

/**
 * GET /farms/:farmId/lip-submissions
 * List all LIP submission records for this farm.
 */
router.get("/farms/:farmId/lip-submissions", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const submissions = await db.select().from(lipSubmissionsTable).where(eq(lipSubmissionsTable.farmId, farmId)).orderBy(desc(lipSubmissionsTable.createdAt)).limit(200);
  res.json({ submissions });
});

/**
 * POST /farms/:farmId/lip-submit-movement/:movementId
 * Submit a cattle movement notification to the LIS LIP API.
 * Works in sandbox mode if LIS_LIP_USE_PRODUCTION is not set or subscription
 * returns 403 (pending approval). Builds and logs the payload regardless.
 */
router.post("/farms/:farmId/lip-submit-movement/:movementId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const movementId = parseInt(req.params.movementId as string);

  const [movement] = await db.select().from(livestockMovementsTable).where(and(eq(livestockMovementsTable.id, movementId), eq(livestockMovementsTable.farmId, farmId)));
  if (!movement) { res.status(404).json({ error: "Movement not found" }); return; }

  const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
  const [farm] = await db.select().from(farmsTable).where(eq(farmsTable.id, farmId));

  // Determine access token — refresh if expired
  let accessToken: string = decryptLipToken(tokenRow?.platformAccessToken);
  if (!isLipSandboxMode() && tokenRow?.isConfigured) {
    const nowPlusBuffer = new Date(Date.now() + 120_000);
    const isExpired = !accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer);
    if (isExpired && tokenRow.lipRefreshToken) {
      const refreshResult = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
      if (refreshResult.success && refreshResult.accessToken) {
        accessToken = refreshResult.accessToken;
        await db.update(lipFarmTokensTable).set({
          platformAccessToken: encryptCredential(refreshResult.accessToken),
          ...(refreshResult.refreshToken ? { lipRefreshToken: encryptCredential(refreshResult.refreshToken) } : {}),
          ...(refreshResult.expiresIn ? { tokenExpiresAt: new Date(Date.now() + refreshResult.expiresIn * 1000) } : {}),
          updatedAt: new Date(),
        }).where(eq(lipFarmTokensTable.farmId, farmId));
      }
    }
  }

  const movDate = movement.movementDate ? new Date(movement.movementDate).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);
  const holdingCph = (farm as any)?.bcmsHoldingNumber ?? movement.fromLocation ?? movement.toLocation ?? "";
  const movType: "ON" | "OFF" = movement.movementType === "on" ? "ON" : "OFF";

  const [submission] = await db.insert(lipSubmissionsTable).values({
    farmId, movementId, submissionType: "movement",
    status: "pending", sandboxMode: isLipSandboxMode(), submittedAt: new Date(),
  }).returning();

  try {
    const result = await submitLipMovement({
      accessToken,
      holdingCph,
      movementDate: movDate,
      movementType: movType,
      fromCph: movement.fromLocation ?? holdingCph,
      toCph: movement.toLocation ?? holdingCph,
      earTagNumbers: movement.earTagNumbers ?? undefined,
      numberOfAnimals: movement.numberOfAnimals ?? 1,
      licenceNumber: movement.licenceNumber ?? undefined,
      isInBusinessMove: movement.movementType === "between",
      haulierName: (movement as any).haulierCompany ?? undefined,
    });

    await db.update(lipSubmissionsTable).set({
      sandboxMode: result.sandbox,
      lipReference: result.lipReference,
      asyncRequestId: result.asyncRequestId,
      errorMessage: result.errorMessage,
      requestPayload: result.requestPayload as any,
      responsePayload: result.responsePayload as any,
      status: result.asyncPending ? "async-pending" : (result.success ? "submitted" : "failed"),
      acknowledgedAt: result.success && !result.asyncPending ? new Date() : undefined,
      updatedAt: new Date(),
    }).where(eq(lipSubmissionsTable.id, submission.id));

    if (result.success && !result.asyncPending) {
      await db.update(livestockMovementsTable).set({
        legalNotificationSubmitted: true,
        legalNotificationDate: new Date(),
        bcmsSubmissionRef: result.lipReference ?? `LIP-SANDBOX-${submission.id}`,
      }).where(eq(livestockMovementsTable.id, movementId));
    }

    res.json({ success: result.success, sandbox: result.sandbox, reference: result.lipReference, asyncPending: result.asyncPending, asyncRequestId: result.asyncRequestId, subscriptionPending: result.subscriptionPending, error: result.errorMessage });
  } catch (err: any) {
    await db.update(lipSubmissionsTable).set({ status: "failed", errorMessage: err?.message ?? "Unknown error", updatedAt: new Date() }).where(eq(lipSubmissionsTable.id, submission.id));
    res.status(500).json({ error: err?.message ?? "LIP submission failed" });
  }
});

/**
 * POST /farms/:farmId/lip-submit-death/:mortalityId
 * Register a cattle death with the LIS LIP API.
 */
router.post("/farms/:farmId/lip-submit-death/:mortalityId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const mortalityId = parseInt(req.params.mortalityId as string);

  const [mortality] = await db.select().from(livestockMortalityTable).where(and(eq(livestockMortalityTable.id, mortalityId), eq(livestockMortalityTable.farmId, farmId)));
  if (!mortality) { res.status(404).json({ error: "Mortality record not found" }); return; }

  const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
  const [farm] = await db.select().from(farmsTable).where(eq(farmsTable.id, farmId));

  let accessToken: string = decryptLipToken(tokenRow?.platformAccessToken);
  if (!isLipSandboxMode() && tokenRow?.isConfigured) {
    const nowPlusBuffer = new Date(Date.now() + 120_000);
    const isExpired = !accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer);
    if (isExpired && tokenRow.lipRefreshToken) {
      const refreshResult = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
      if (refreshResult.success && refreshResult.accessToken) {
        accessToken = refreshResult.accessToken;
        await db.update(lipFarmTokensTable).set({
          platformAccessToken: encryptCredential(refreshResult.accessToken),
          ...(refreshResult.refreshToken ? { lipRefreshToken: encryptCredential(refreshResult.refreshToken) } : {}),
          ...(refreshResult.expiresIn ? { tokenExpiresAt: new Date(Date.now() + refreshResult.expiresIn * 1000) } : {}),
          updatedAt: new Date(),
        }).where(eq(lipFarmTokensTable.farmId, farmId));
      }
    }
  }

  const deathDate = mortality.dateOfDeath ? new Date(mortality.dateOfDeath).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);
  const holdingCph = (farm as any)?.bcmsHoldingNumber ?? "";

  // Look up calving record to get birthDate and sex (not stored on mortality table)
  const [calving] = mortality.tagNumber
    ? await db.select({ calvingDate: dairyCalvingRecordsTable.calvingDate, calfSex: dairyCalvingRecordsTable.calfSex })
        .from(dairyCalvingRecordsTable)
        .where(and(eq(dairyCalvingRecordsTable.farmId, farmId), eq(dairyCalvingRecordsTable.calfEarTag, mortality.tagNumber)))
        .orderBy(desc(dairyCalvingRecordsTable.calvingDate))
        .limit(1)
    : [undefined];
  const birthDate = calving?.calvingDate ? new Date(calving.calvingDate).toISOString().slice(0, 10) : undefined;
  const sex = calving?.calfSex ?? undefined;

  const [submission] = await db.insert(lipSubmissionsTable).values({
    farmId, mortalityId, submissionType: "death",
    status: "pending", sandboxMode: isLipSandboxMode(), submittedAt: new Date(),
  }).returning();

  try {
    const result = await submitLipDeath({
      accessToken,
      holdingCph,
      deathDate,
      earTag: mortality.tagNumber ?? undefined,
      sex,
      birthDate,
      causeOfDeath: mortality.causeOfDeath ?? undefined,
      disposalMethod: mortality.disposalMethod ?? undefined,
    });

    await db.update(lipSubmissionsTable).set({
      status: result.asyncPending ? "async-pending" : (result.success ? "submitted" : "failed"),
      sandboxMode: result.sandbox,
      lipReference: result.lipReference,
      asyncRequestId: result.asyncRequestId,
      errorMessage: result.errorMessage,
      requestPayload: result.requestPayload as any,
      responsePayload: result.responsePayload as any,
      acknowledgedAt: result.success && !result.asyncPending ? new Date() : undefined,
      updatedAt: new Date(),
    }).where(eq(lipSubmissionsTable.id, submission.id));

    if (result.success && !result.asyncPending) {
      await db.update(livestockMortalityTable).set({
        bcmsNotified: true,
        bcmsNotificationRef: result.lipReference ?? `LIP-DEATH-${submission.id}`,
      }).where(eq(livestockMortalityTable.id, mortalityId));
    }

    res.json({ success: result.success, sandbox: result.sandbox, reference: result.lipReference, asyncPending: result.asyncPending, asyncRequestId: result.asyncRequestId, subscriptionPending: result.subscriptionPending, error: result.errorMessage });
  } catch (err: any) {
    await db.update(lipSubmissionsTable).set({ status: "failed", errorMessage: err?.message ?? "Unknown error", updatedAt: new Date() }).where(eq(lipSubmissionsTable.id, submission.id));
    res.status(500).json({ error: err?.message ?? "LIP death submission failed" });
  }
});

/**
 * POST /farms/:farmId/lip-submit-birth/:calvingId
 * Register a cattle birth (calving) with the LIS LIP API.
 */
router.post("/farms/:farmId/lip-submit-birth/:calvingId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const calvingId = parseInt(req.params.calvingId as string);

  const [calving] = await db.select().from(dairyCalvingRecordsTable).where(and(eq(dairyCalvingRecordsTable.id, calvingId), eq(dairyCalvingRecordsTable.farmId, farmId)));
  if (!calving) { res.status(404).json({ error: "Calving record not found" }); return; }

  const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
  const [farm] = await db.select().from(farmsTable).where(eq(farmsTable.id, farmId));

  let accessToken: string = decryptLipToken(tokenRow?.platformAccessToken);
  if (!isLipSandboxMode() && tokenRow?.isConfigured) {
    const nowPlusBuffer = new Date(Date.now() + 120_000);
    const isExpired = !accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer);
    if (isExpired && tokenRow.lipRefreshToken) {
      const refreshResult = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
      if (refreshResult.success && refreshResult.accessToken) {
        accessToken = refreshResult.accessToken;
        await db.update(lipFarmTokensTable).set({
          platformAccessToken: encryptCredential(refreshResult.accessToken),
          ...(refreshResult.refreshToken ? { lipRefreshToken: encryptCredential(refreshResult.refreshToken) } : {}),
          ...(refreshResult.expiresIn ? { tokenExpiresAt: new Date(Date.now() + refreshResult.expiresIn * 1000) } : {}),
          updatedAt: new Date(),
        }).where(eq(lipFarmTokensTable.farmId, farmId));
      }
    }
  }

  const birthDate = calving.calvingDate ? new Date(calving.calvingDate).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);
  const holdingCph = (farm as any)?.bcmsHoldingNumber ?? "";

  const [submission] = await db.insert(lipSubmissionsTable).values({
    farmId, calvingId, submissionType: "birth",
    status: "pending", sandboxMode: isLipSandboxMode(), submittedAt: new Date(),
  }).returning();

  try {
    const result = await submitLipBirth({
      accessToken,
      holdingCph,
      birthDate,
      calfEarTag: calving.calfEarTag ?? undefined,
      calfSex: calving.calfSex ?? undefined,
      calfBreed: calving.calfBreed ?? undefined,
      damEarTag: calving.cowEarTag ?? undefined,
      assistanceRequired: calving.assistanceRequired ?? undefined,
      numberOfCalves: calving.numberOfCalves ?? undefined,
      conceptionMethod: calving.conceptionMethod ?? undefined,
    });

    await db.update(lipSubmissionsTable).set({
      status: result.asyncPending ? "async-pending" : (result.success ? "submitted" : "failed"),
      sandboxMode: result.sandbox,
      lipReference: result.lipReference,
      asyncRequestId: result.asyncRequestId,
      errorMessage: result.errorMessage,
      requestPayload: result.requestPayload as any,
      responsePayload: result.responsePayload as any,
      acknowledgedAt: result.success && !result.asyncPending ? new Date() : undefined,
      updatedAt: new Date(),
    }).where(eq(lipSubmissionsTable.id, submission.id));

    res.json({ success: result.success, sandbox: result.sandbox, reference: result.lipReference, asyncPending: result.asyncPending, asyncRequestId: result.asyncRequestId, subscriptionPending: result.subscriptionPending, error: result.errorMessage });
  } catch (err: any) {
    await db.update(lipSubmissionsTable).set({ status: "failed", errorMessage: err?.message ?? "Unknown error", updatedAt: new Date() }).where(eq(lipSubmissionsTable.id, submission.id));
    res.status(500).json({ error: err?.message ?? "LIP birth submission failed" });
  }
});

