/**
 * GET /farms/:farmId/lip-lost-found
 * List all lost & found records for this farm.
 */
router.get("/farms/:farmId/lip-lost-found", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const rows = await db.select().from(lipLostFoundTable).where(eq(lipLostFoundTable.farmId, farmId)).orderBy(desc(lipLostFoundTable.eventDate));
  res.json({ records: rows });
});

/**
 * POST /farms/:farmId/lip-lost-found
 * Create a new lost/found/stolen animal record and (optionally) submit to LIP.
 */
router.post("/farms/:farmId/lip-lost-found", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const { earTag, siteIdentifier, status, eventDate, crimeReferenceNumber, foundDead, notes, submitToLip } = req.body as {
    earTag: string; siteIdentifier?: string; status: string; eventDate: string;
    crimeReferenceNumber?: string; foundDead?: boolean; notes?: string; submitToLip?: boolean;
  };

  if (!earTag || !status || !eventDate) { res.status(400).json({ error: "earTag, status and eventDate are required" }); return; }

  const eventDateStr = new Date(eventDate).toISOString().slice(0, 10);
  const [row] = await db.insert(lipLostFoundTable).values({
    farmId, earTag, siteIdentifier: siteIdentifier ?? null,
    status, eventDate: eventDateStr,
    crimeReferenceNumber: crimeReferenceNumber ?? null,
    foundDead: foundDead ?? null,
    notes: notes ?? null,
    lipStatus: "pending",
    sandboxMode: isLipSandboxMode(),
    createdAt: new Date(), updatedAt: new Date(),
  }).returning();

  if (!submitToLip) { res.json({ record: row }); return; }

  const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
  const [farm] = await db.select().from(farmsTable).where(eq(farmsTable.id, farmId));
  const holdingCph = (farm as any)?.bcmsHoldingNumber ?? siteIdentifier ?? "";
  let accessToken: string = decryptLipToken(tokenRow?.platformAccessToken);

  if (!isLipSandboxMode() && tokenRow?.isConfigured) {
    const nowPlusBuffer = new Date(Date.now() + 120_000);
    const isExpired = !accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer);
    if (isExpired && tokenRow.lipRefreshToken) {
      const refreshResult = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
      if (refreshResult.success && refreshResult.accessToken) {
        accessToken = refreshResult.accessToken;
        await db.update(lipFarmTokensTable).set({ platformAccessToken: encryptCredential(refreshResult.accessToken), updatedAt: new Date() }).where(eq(lipFarmTokensTable.farmId, farmId));
      }
    }
  }

  try {
    const result = await submitLipLostFound({
      accessToken, identifier: earTag, holdingCph,
      status: status as "lost" | "found" | "stolen",
      eventDate: new Date(eventDate).toISOString().slice(0, 10),
      crimeReferenceNumber: crimeReferenceNumber ?? undefined,
      foundDead: foundDead ?? undefined,
    });

    const [updated] = await db.update(lipLostFoundTable).set({
      lipStatus: result.success ? "submitted" : "failed",
      sandboxMode: result.sandbox,
      lipReference: result.lipReference,
      errorMessage: result.errorMessage,
      requestPayload: result.requestPayload as any,
      responsePayload: result.responsePayload as any,
      submittedAt: new Date(),
      updatedAt: new Date(),
    }).where(eq(lipLostFoundTable.id, row.id)).returning();

    res.json({ record: updated, success: result.success, sandbox: result.sandbox, reference: result.lipReference, error: result.errorMessage });
  } catch (err: any) {
    await db.update(lipLostFoundTable).set({ lipStatus: "failed", errorMessage: err?.message ?? "Unknown error", updatedAt: new Date() }).where(eq(lipLostFoundTable.id, row.id));
    res.status(500).json({ error: err?.message ?? "LIP lost/found submission failed" });
  }
});

/**
 * PUT /farms/:farmId/lip-lost-found/:id
 * Update a lost & found record (e.g. resubmit, update notes).
 */
router.put("/farms/:farmId/lip-lost-found/:id", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const id = parseInt(req.params.id as string);

  const [existing] = await db.select().from(lipLostFoundTable).where(and(eq(lipLostFoundTable.id, id), eq(lipLostFoundTable.farmId, farmId)));
  if (!existing) { res.status(404).json({ error: "Record not found" }); return; }

  const { earTag, siteIdentifier, status, eventDate, crimeReferenceNumber, foundDead, notes } = req.body as {
    earTag?: string; siteIdentifier?: string; status?: string; eventDate?: string;
    crimeReferenceNumber?: string; foundDead?: boolean; notes?: string;
  };

  const updateData: Record<string, unknown> = { updatedAt: new Date() };
  if (earTag !== undefined) updateData.earTag = earTag;
  if (siteIdentifier !== undefined) updateData.siteIdentifier = siteIdentifier;
  if (status !== undefined) updateData.status = status;
  if (eventDate !== undefined) updateData.eventDate = new Date(eventDate).toISOString().slice(0, 10);
  if (crimeReferenceNumber !== undefined) updateData.crimeReferenceNumber = crimeReferenceNumber;
  if (foundDead !== undefined) updateData.foundDead = foundDead;
  if (notes !== undefined) updateData.notes = notes;

  const [updated] = await db.update(lipLostFoundTable).set(updateData as any).where(eq(lipLostFoundTable.id, id)).returning();

  res.json({ record: updated });
});

// ─── LIP Movement Confirmation / Cancellation ─────────────────────────────

/**
 * POST /farms/:farmId/lip-confirm-movement
 * Confirm or reject a movement as the receiving holding.
 */
router.post("/farms/:farmId/lip-confirm-movement", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const { lipReference, action, rejectionReasonId, rejectionReason, submissionId } = req.body as {
    lipReference: string; action: "accept" | "reject";
    rejectionReasonId?: string; rejectionReason?: string; submissionId?: number;
  };

  if (!lipReference || !action) { res.status(400).json({ error: "lipReference and action are required" }); return; }

  const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
  let accessToken: string = decryptLipToken(tokenRow?.platformAccessToken);

  if (!isLipSandboxMode() && tokenRow?.isConfigured) {
    const nowPlusBuffer = new Date(Date.now() + 120_000);
    const isExpired = !accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer);
    if (isExpired && tokenRow.lipRefreshToken) {
      const refreshResult = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
      if (refreshResult.success && refreshResult.accessToken) {
        accessToken = refreshResult.accessToken;
        await db.update(lipFarmTokensTable).set({ platformAccessToken: encryptCredential(refreshResult.accessToken), updatedAt: new Date() }).where(eq(lipFarmTokensTable.farmId, farmId));
      }
    }
  }

  const result = await confirmLipMovement({ accessToken, movementNumber: lipReference, action, rejectionReasonId, rejectionReason });

  if (submissionId) {
    await db.update(lipSubmissionsTable).set({
      confirmedAt: new Date(),
      confirmedAction: action,
      status: result.success ? (action === "accept" ? "confirmed" : "rejected") : "failed",
      errorMessage: result.errorMessage ?? undefined,
      updatedAt: new Date(),
    }).where(eq(lipSubmissionsTable.id, submissionId));
  }

  res.json({ success: result.success, sandbox: result.sandbox, reference: result.lipReference, subscriptionPending: result.subscriptionPending, error: result.errorMessage });
});

/**
 * POST /farms/:farmId/lip-cancel-movement
 * Cancel (delete) a previously submitted movement.
 */
router.post("/farms/:farmId/lip-cancel-movement", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const { lipReference, submissionId } = req.body as { lipReference: string; submissionId?: number };

  if (!lipReference) { res.status(400).json({ error: "lipReference is required" }); return; }

  const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
  let accessToken: string = decryptLipToken(tokenRow?.platformAccessToken);

  if (!isLipSandboxMode() && tokenRow?.isConfigured) {
    const nowPlusBuffer = new Date(Date.now() + 120_000);
    const isExpired = !accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer);
    if (isExpired && tokenRow.lipRefreshToken) {
      const refreshResult = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
      if (refreshResult.success && refreshResult.accessToken) {
        accessToken = refreshResult.accessToken;
        await db.update(lipFarmTokensTable).set({ platformAccessToken: encryptCredential(refreshResult.accessToken), updatedAt: new Date() }).where(eq(lipFarmTokensTable.farmId, farmId));
      }
    }
  }

  const result = await cancelLipMovement(accessToken, lipReference);

  if (submissionId) {
    await db.update(lipSubmissionsTable).set({
      cancelledAt: new Date(),
      status: result.success ? "cancelled" : "cancel-failed",
      errorMessage: result.errorMessage ?? undefined,
      updatedAt: new Date(),
    }).where(eq(lipSubmissionsTable.id, submissionId));
  }

  res.json({ success: result.success, sandbox: result.sandbox, reference: result.lipReference, subscriptionPending: result.subscriptionPending, error: result.errorMessage });
});

/**
 * GET /farms/:farmId/lip-rejection-reasons
 * Fetch the LIS-controlled list of movement rejection reason codes.
 * Returns [] if the farm has no active LIP token.
 */
router.get("/farms/:farmId/lip-rejection-reasons", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  try {
    const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
    if (!tokenRow?.platformAccessToken) { res.json({ reasons: [] }); return; }
    let accessToken = decryptLipToken(tokenRow?.platformAccessToken);
    if (tokenRow.lipRefreshToken) {
      const nowPlusBuffer = new Date(Date.now() + 120_000);
      if (!accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer)) {
        const r = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
        if (r.success && r.accessToken) {
          accessToken = r.accessToken;
          await db.update(lipFarmTokensTable).set({ platformAccessToken: encryptCredential(r.accessToken), ...(r.refreshToken ? { lipRefreshToken: encryptCredential(r.refreshToken) } : {}), ...(r.expiresIn ? { tokenExpiresAt: new Date(Date.now() + r.expiresIn * 1000) } : {}), updatedAt: new Date() }).where(eq(lipFarmTokensTable.farmId, farmId));
        }
      }
    }
    const reasons = await getLipRejectionReasons(accessToken);
    res.json({ reasons });
  } catch {
    res.json({ reasons: [] });
  }
});

/**
 * POST /farms/:farmId/lip-check-async/:submissionId
 * Poll GET /requeststatus/{asyncRequestId} for a submission in "async-pending" state.
 * Updates the submission record to "submitted" or "failed" when resolved.
 */
router.post("/farms/:farmId/lip-check-async/:submissionId", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;
  const submissionId = parseInt(req.params.submissionId as string);
  const [submission] = await db.select().from(lipSubmissionsTable).where(and(eq(lipSubmissionsTable.id, submissionId), eq(lipSubmissionsTable.farmId, farmId)));
  if (!submission) { res.status(404).json({ error: "Submission not found" }); return; }
  if (!submission.asyncRequestId) { res.status(400).json({ error: "No async request ID on this submission" }); return; }

  const [tokenRow] = await db.select().from(lipFarmTokensTable).where(eq(lipFarmTokensTable.farmId, farmId));
  if (!tokenRow?.platformAccessToken) { res.status(400).json({ error: "LIP not connected" }); return; }
  let accessToken = decryptLipToken(tokenRow?.platformAccessToken);
  if (tokenRow.lipRefreshToken) {
    const nowPlusBuffer = new Date(Date.now() + 120_000);
    if (!accessToken || (tokenRow.tokenExpiresAt && new Date(tokenRow.tokenExpiresAt) < nowPlusBuffer)) {
      const r = await refreshLipToken(decryptLipToken(tokenRow.lipRefreshToken));
      if (r.success && r.accessToken) {
        accessToken = r.accessToken;
        await db.update(lipFarmTokensTable).set({ platformAccessToken: encryptCredential(r.accessToken), ...(r.refreshToken ? { lipRefreshToken: encryptCredential(r.refreshToken) } : {}), ...(r.expiresIn ? { tokenExpiresAt: new Date(Date.now() + r.expiresIn * 1000) } : {}), updatedAt: new Date() }).where(eq(lipFarmTokensTable.farmId, farmId));
      }
    }
  }

  const statusResult = await checkLipRequestStatus(accessToken, submission.asyncRequestId);
  const isCompleted = /completed/i.test(statusResult.status);
  const isFailed    = /failed/i.test(statusResult.status);

  if (isCompleted || isFailed) {
    await db.update(lipSubmissionsTable).set({
      status: isCompleted ? "submitted" : "failed",
      lipReference: statusResult.lipReference ?? submission.lipReference,
      responsePayload: statusResult.result as any,
      acknowledgedAt: isCompleted ? new Date() : undefined,
      errorMessage: statusResult.errorMessage ?? undefined,
      updatedAt: new Date(),
    }).where(eq(lipSubmissionsTable.id, submissionId));

    if (isCompleted && submission.movementId && statusResult.lipReference) {
      await db.update(livestockMovementsTable).set({ legalNotificationSubmitted: true, legalNotificationDate: new Date(), bcmsSubmissionRef: statusResult.lipReference }).where(eq(livestockMovementsTable.id, submission.movementId));
    }
    if (isCompleted && submission.mortalityId && statusResult.lipReference) {
      await db.update(livestockMortalityTable).set({ bcmsNotified: true, bcmsNotificationRef: statusResult.lipReference }).where(eq(livestockMortalityTable.id, submission.mortalityId));
    }
  }

  res.json({ status: statusResult.status, reference: statusResult.lipReference, resolved: isCompleted || isFailed });
});

// ─── LIS Herd Sync ──────────────────────────────────────────────────────────

/**
 * POST /api/farms/:farmId/lis/sync-herds
 * Fetches herds and flocks from the LIS CLA API for this farm's CPH number.
 * Tries multiple endpoint patterns and returns both structured results and raw
 * responses so we can discover the correct CLA API paths in the sandbox.
 */
router.post("/farms/:farmId/lis/sync-herds", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const [creds] = await db.select().from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));
  if (!creds?.isConfigured) {
    res.status(400).json({ success: false, message: "LIS credentials not configured. Save and test your credentials first." });
    return;
  }

  // Internal sandbox mode (no LIS_SUBSCRIPTION_KEY) — return simulated empty result
  if (isLisSandboxMode()) {
    res.json({
      success: true,
      sandbox: true,
      cphNumber: null,
      message: "Running in internal sandbox mode — no live LIS call made. Set LIS_SUBSCRIPTION_KEY to enable real API calls.",
      herds: [],
      attempts: {},
    });
    return;
  }

  // Get or refresh access token
  const password = decryptCredential(creds.lisPasswordEncrypted ?? "");
  let accessToken = creds.accessToken ?? undefined;
  const tokenExpired = !accessToken || (creds.tokenExpiresAt && new Date(creds.tokenExpiresAt) < new Date(Date.now() + 60_000));
  if (tokenExpired) {
    // ── Try OAuth refresh token first ────────────────────────────────────────
    if (creds.refreshToken) {
      const refreshResult = await refreshLisToken(creds.refreshToken);
      if (refreshResult.success && refreshResult.accessToken) {
        accessToken = refreshResult.accessToken;
        await db.update(lisFarmTokensTable).set({
          accessToken,
          refreshToken: refreshResult.refreshToken ?? undefined,
          tokenExpiresAt: refreshResult.expiresIn ? new Date(Date.now() + refreshResult.expiresIn * 1000) : undefined,
          updatedAt: new Date(),
        }).where(eq(lisFarmTokensTable.farmId, farmId));
      } else {
        accessToken = undefined;
      }
    }
    // ── Legacy ROPC fallback ─────────────────────────────────────────────────
    if (!accessToken && creds.lisPasswordEncrypted) {
      const password = decryptCredential(creds.lisPasswordEncrypted ?? "");
      const tokenResult = await fetchLisToken(creds.lisUsername!, password);
      if (!tokenResult.success || !tokenResult.accessToken) {
        res.status(401).json({ success: false, message: `Re-authentication failed: ${tokenResult.errorMessage ?? "unknown error"}. Try signing in again via 'Sign in with LIS'.` });
        return;
      }
      accessToken = tokenResult.accessToken;
      await db.update(lisFarmTokensTable).set({
        accessToken,
        refreshToken: tokenResult.refreshToken ?? undefined,
        tokenExpiresAt: tokenResult.expiresIn ? new Date(Date.now() + tokenResult.expiresIn * 1000) : undefined,
        updatedAt: new Date(),
      }).where(eq(lisFarmTokensTable.farmId, farmId));
    }
    if (!accessToken) {
      res.status(401).json({ success: false, message: "LIS token has expired. Please click 'Sign in with LIS' in Farm Settings to reconnect." });
      return;
    }
  }

  // Fetch the farm's CPH number
  const [farm] = await db.select({ cphNumber: farmsTable.cphNumber }).from(farmsTable).where(eq(farmsTable.id, farmId));
  const cphNumber = farm?.cphNumber ?? "";

  if (!cphNumber) {
    res.status(400).json({ success: false, message: "No CPH number set for this farm. Please add your CPH number in Farm Settings before syncing." });
    return;
  }

  // ── 1. Validate CPH with LIS ─────────────────────────────────────────────
  // CLA API: POST /Holdings/ValidHoldings
  const cphValidation = await callLisApi(accessToken!, "/Holdings/ValidHoldings", "POST", {
    content: { holdings: [cphNumber] },
  });

  let cphValid: boolean | null = null;
  let cphState: string | null = null;
  if (cphValidation.data && typeof cphValidation.data === "object") {
    const d = cphValidation.data as any;
    const results: Array<{ holding: string; state: string; propertyName?: string }> =
      d.validateResults ?? d.content?.validateResults ?? d.value ?? d.items ?? [];
    const match = results.find(
      (r) => r.holding === cphNumber || r.holding?.replace(/[/-]/g, "") === cphNumber.replace(/[/-]/g, ""),
    );
    cphState = match?.state ?? null;
    cphValid = cphState != null && /^valid$/i.test(cphState);
  }

  // ── 2. Fetch pending movement reviews for sheep ───────────────────────────
  const encodedCph = encodeURIComponent(cphNumber);
  const reviewResult = await callLisApi(
    accessToken!,
    `/HoldingMovementForReviews/ReviewBySpecies(species='Sheep',holding='${encodedCph}')`,
  );
  let pendingReviews: any[] = [];
  if (reviewResult.data) {
    const d = reviewResult.data as any;
    const inner = d.value ?? d.content?.movements ?? d.content?.items ?? d.items;
    if (Array.isArray(inner)) pendingReviews = inner;
    else if (Array.isArray(d)) pendingReviews = d;
  }

  // ── 3. Fetch transfer requests (outbound movements) ───────────────────────
  const transferResult = await callLisApi(accessToken!, "/TransferRequests?$top=50");
  let recentTransfers: any[] = [];
  if (transferResult.data) {
    const d = transferResult.data as any;
    const inner = d.value ?? d.content?.items ?? d.items;
    if (Array.isArray(inner)) recentTransfers = inner;
    else if (Array.isArray(d)) recentTransfers = d;
  }

  // ── 4. Fetch approved movements (full history) ────────────────────────────
  const approvedResult = await callLisApi(accessToken!, "/ApprovedMovements?$top=200");
  let approvedMovements: any[] = [];
  if (approvedResult.data) {
    const d = approvedResult.data as any;
    const inner = d.value ?? d.content?.items ?? d.items;
    if (Array.isArray(inner)) approvedMovements = inner;
    else if (Array.isArray(d)) approvedMovements = d;
  }

  // ── 5. Import fetched records into the database ───────────────────────────
  const importCounts = { approved: 0, transfers: 0, reviews: 0, errors: 0 };

  // Flexible field extractors — the CLA API may use different names across versions
  const cphNorm = (s: string | null | undefined) => (s ?? "").replace(/[^0-9]/g, "");
  const extractRef = (item: any): string | null =>
    String(item?.id ?? item?.reference ?? item?.movementReference ?? item?.transferId ?? item?.requestId ?? item?.reviewId ?? "").trim() || null;
  const extractDate = (item: any): Date | null => {
    const raw = item?.movementDate ?? item?.transferDate ?? item?.requestDate ?? item?.dateOfMovement ?? item?.date ?? item?.createdDate;
    if (!raw) return null;
    const d = new Date(raw);
    return isNaN(d.getTime()) ? null : d;
  };
  const extractFrom = (item: any): string | null =>
    item?.fromHolding ?? item?.fromCph ?? item?.holdingFrom ?? item?.fromLocation ?? item?.sourceCph ?? item?.departureHolding ?? null;
  const extractTo = (item: any): string | null =>
    item?.toHolding ?? item?.toCph ?? item?.holdingTo ?? item?.toLocation ?? item?.destinationCph ?? item?.destinationHolding ?? null;
  const extractCount = (item: any): number | null => {
    const v = item?.numberOfAnimals ?? item?.animalCount ?? item?.quantity ?? item?.count ?? item?.headCount;
    return v != null ? Number(v) : null;
  };

  const upsertMovement = async (item: any, source: "approved" | "transfer_request" | "movement_review") => {
    const ref = extractRef(item);
    if (!ref) return;
    const movDate = extractDate(item);
    if (!movDate) return;
    const lisRef = `${source}:${ref}`;
    const from = extractFrom(item);
    const to = extractTo(item);
    // Determine direction: arrival = animals came to this farm, departure = animals left
    const toNorm = cphNorm(to);
    const cphN = cphNorm(cphNumber);
    const isArrival = toNorm === cphN || source === "movement_review";
    const movType = isArrival ? "arrival" : "departure";
    const legalDone = source === "approved";

    const [existing] = await db.select({ id: livestockMovementsTable.id })
      .from(livestockMovementsTable)
      .where(and(eq(livestockMovementsTable.farmId, farmId), eq(livestockMovementsTable.lisMovementRef, lisRef)));

    if (existing) {
      await db.update(livestockMovementsTable).set({
        movementDate: movDate,
        fromLocation: from,
        toLocation: to,
        numberOfAnimals: extractCount(item),
        lisRawData: item,
        lisImportedAt: new Date(),
      }).where(eq(livestockMovementsTable.id, existing.id));
    } else {
      await db.insert(livestockMovementsTable).values({
        farmId,
        movementType: movType,
        movementDate: movDate,
        fromLocation: from,
        toLocation: to,
        numberOfAnimals: extractCount(item),
        species: "Sheep",
        legalNotificationSubmitted: legalDone,
        lisMovementRef: lisRef,
        lisSource: source,
        lisRawData: item,
        lisImportedAt: new Date(),
      });
    }
  };

  for (const item of approvedMovements) {
    try { await upsertMovement(item, "approved"); importCounts.approved++; }
    catch { importCounts.errors++; }
  }
  for (const item of recentTransfers) {
    try { await upsertMovement(item, "transfer_request"); importCounts.transfers++; }
    catch { importCounts.errors++; }
  }
  for (const item of pendingReviews) {
    try { await upsertMovement(item, "movement_review"); importCounts.reviews++; }
    catch { importCounts.errors++; }
  }

  // ── 6. Update sync timestamp on the token record ──────────────────────────
  const totalImported = importCounts.approved + importCounts.transfers + importCounts.reviews;
  const syncSummary = [
    cphValid ? `CPH ${cphNumber} valid` : `CPH ${cphNumber} not recognised`,
    importCounts.approved > 0 ? `${importCounts.approved} approved movements imported` : null,
    importCounts.transfers > 0 ? `${importCounts.transfers} transfer requests imported` : null,
    importCounts.reviews > 0 ? `${importCounts.reviews} pending reviews imported` : null,
    totalImported === 0 ? "No movement records found in LIS for this holding" : null,
  ].filter(Boolean).join(". ");

  const historyEntry = {
    syncedAt: new Date().toISOString(),
    summary: syncSummary,
    imported: importCounts,
    cphValid,
    cphNumber,
  };
  const existingHistory = Array.isArray(creds?.lisSyncHistory) ? (creds.lisSyncHistory as unknown[]) : [];
  const updatedHistory = [historyEntry, ...existingHistory].slice(0, 20);

  await db.update(lisFarmTokensTable).set({
    lisLastSyncedAt: new Date(),
    lisLastSyncSummary: syncSummary,
    lisSyncHistory: updatedHistory,
    updatedAt: new Date(),
  }).where(eq(lisFarmTokensTable.farmId, farmId));

  // ── 7. Build response ─────────────────────────────────────────────────────
  const messages: string[] = [];
  if (cphValid === true) messages.push(`CPH ${cphNumber} is registered in LIS`);
  else if (cphValid === false) messages.push(`CPH ${cphNumber} is not recognised in LIS (state: ${cphState ?? "unknown"})`);
  else if (!cphValidation.ok) messages.push(`CPH validation failed (HTTP ${cphValidation.status})`);

  if (importCounts.approved > 0) messages.push(`${importCounts.approved} approved movement(s) imported`);
  if (importCounts.transfers > 0) messages.push(`${importCounts.transfers} transfer request(s) imported`);
  if (importCounts.reviews > 0) messages.push(`${importCounts.reviews} pending review(s) imported`);
  if (totalImported === 0 && (cphValidation.ok || reviewResult.ok || transferResult.ok || approvedResult.ok))
    messages.push("No movement records found in LIS for this holding yet");
  if (importCounts.errors > 0) messages.push(`${importCounts.errors} record(s) could not be imported`);

  const anySuccess = cphValidation.ok || reviewResult.ok || transferResult.ok || approvedResult.ok;
  res.json({
    success: anySuccess,
    sandbox: false,
    cphNumber,
    cphValid,
    imported: importCounts,
    message: messages.length > 0 ? messages.join(". ") : "LIS sync completed — no data found for this holding.",
    pendingReviews,
    recentTransfers,
    approvedMovements,
    attempts: {
      "POST /Holdings/ValidHoldings": { status: cphValidation.status, ok: cphValidation.ok, data: cphValidation.data },
      "GET /HoldingMovementForReviews/ReviewBySpecies": { status: reviewResult.status, ok: reviewResult.ok, data: reviewResult.data },
      "GET /TransferRequests": { status: transferResult.status, ok: transferResult.ok, data: transferResult.data },
      "GET /ApprovedMovements": { status: approvedResult.status, ok: approvedResult.ok, data: approvedResult.data },
    },
  });
});

// ─── LIS Inbound Movements (pending reviews from other keepers) ───────────

/**
 * GET /api/farms/:farmId/lis-inbound-movements
 * Returns livestock_movements rows that were synced from LIS with
 * lisSource = "movement_review" and have not yet been reviewed.
 */
router.get("/farms/:farmId/lis-inbound-movements", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const rows = await db
    .select()
    .from(livestockMovementsTable)
    .where(
      and(
        eq(livestockMovementsTable.farmId, farmId),
        eq(livestockMovementsTable.lisSource, "movement_review"),
      ),
    )
    .orderBy(desc(livestockMovementsTable.movementDate));

  res.json(rows);
});

// ─── LIS Review Movement (accept/reject an inbound movement) ─────────────

/**
 * POST /api/farms/:farmId/lis-review-movement
 * Body: { movId: number; isAccepted: boolean; arrivalDate: string }
 * Calls POST /ReviewHoldingMovementRequests on the CLA OData API, then
 * marks the movement in the DB as reviewed (lisSource → "reviewed").
 */
router.post("/farms/:farmId/lis-review-movement", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const { movId, isAccepted, arrivalDate } = req.body as { movId: number; isAccepted: boolean; arrivalDate: string };
  if (!movId) { res.status(400).json({ success: false, error: "movId is required" }); return; }

  const [mov] = await db.select().from(livestockMovementsTable)
    .where(and(eq(livestockMovementsTable.id, movId), eq(livestockMovementsTable.farmId, farmId)));
  if (!mov) { res.status(404).json({ success: false, error: "Movement not found" }); return; }

  // Extract requestId and holding from the raw LIS data stored during sync
  const raw = mov.lisRawData as any;
  const requestId: number = Number(raw?.requestId ?? raw?.id ?? raw?.reviewId ?? 0);
  const holding: string = mov.toLocation ?? "";
  const animalTotal: number = mov.numberOfAnimals ?? raw?.animalTotal ?? 1;

  if (!requestId) {
    res.status(400).json({ success: false, error: "Cannot determine LIS requestId for this movement — try syncing again." });
    return;
  }

  // ── Token retrieval ─────────────────────────────────────────────────────
  const [creds] = await db.select().from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));

  if (isLisSandboxMode()) {
    // Simulate success in sandbox
    await db.update(livestockMovementsTable).set({
      lisSource: isAccepted ? "reviewed_accepted" : "reviewed_rejected",
    }).where(eq(livestockMovementsTable.id, movId));
    res.json({ success: true, sandbox: true, isAccepted });
    return;
  }

  if (!creds?.isConfigured) {
    res.status(400).json({ success: false, error: "LIS not configured for this farm." });
    return;
  }

  let accessToken = creds.accessToken ?? undefined;
  if (!accessToken || (creds.tokenExpiresAt && new Date(creds.tokenExpiresAt) < new Date(Date.now() + 60_000))) {
    if (creds.refreshToken) {
      const r = await refreshLisToken(creds.refreshToken);
      if (r.success && r.accessToken) {
        accessToken = r.accessToken;
        await db.update(lisFarmTokensTable).set({ accessToken, refreshToken: r.refreshToken ?? undefined, tokenExpiresAt: r.expiresIn ? new Date(Date.now() + r.expiresIn * 1000) : undefined, updatedAt: new Date() }).where(eq(lisFarmTokensTable.farmId, farmId));
      }
    }
    if (!accessToken && creds.lisPasswordEncrypted) {
      const pw = decryptCredential(creds.lisPasswordEncrypted);
      const t = await fetchLisToken(creds.lisUsername!, pw);
      if (t.success && t.accessToken) {
        accessToken = t.accessToken;
        await db.update(lisFarmTokensTable).set({ accessToken, refreshToken: t.refreshToken ?? undefined, tokenExpiresAt: t.expiresIn ? new Date(Date.now() + t.expiresIn * 1000) : undefined, updatedAt: new Date() }).where(eq(lisFarmTokensTable.farmId, farmId));
      }
    }
  }
  if (!accessToken) { res.status(401).json({ success: false, error: "LIS token expired — please reconnect via Farm Settings." }); return; }

  const result = await reviewHoldingMovement(accessToken, {
    requestId,
    holding,
    isAccepted,
    arrivalDate: arrivalDate || new Date().toISOString().slice(0, 10),
    animalTotal,
  });

  if (result.ok) {
    await db.update(livestockMovementsTable).set({
      lisSource: isAccepted ? "reviewed_accepted" : "reviewed_rejected",
      legalNotificationSubmitted: isAccepted,
    }).where(eq(livestockMovementsTable.id, movId));
  }

  res.json({ success: result.ok, sandbox: false, isAccepted, error: result.errorMessage });
});

// ─── LIS Undo Movement (withdraw a synced transfer request) ──────────────

/**
 * POST /api/farms/:farmId/lis-undo-movement
 * Body: { movId: number }
 * Extracts the OData requestId from lisMovementRef ("transfer_request:<id>")
 * and calls POST /UndoRequests to withdraw the movement from LIS.
 */
router.post("/farms/:farmId/lis-undo-movement", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = await validateFarmAccess(req, res);
  if (!farmId) return;

  const { movId } = req.body as { movId: number };
  if (!movId) { res.status(400).json({ success: false, error: "movId is required" }); return; }

  const [mov] = await db.select().from(livestockMovementsTable)
    .where(and(eq(livestockMovementsTable.id, movId), eq(livestockMovementsTable.farmId, farmId)));
  if (!mov) { res.status(404).json({ success: false, error: "Movement not found" }); return; }

  // Extract numeric requestId from "transfer_request:12345" or from raw data
  const ref = mov.lisMovementRef ?? "";
  const raw = mov.lisRawData as any;
  const idFromRef = ref.startsWith("transfer_request:") ? parseInt(ref.replace("transfer_request:", "")) : NaN;
  const idFromRaw = Number(raw?.requestId ?? raw?.id ?? raw?.transferId ?? NaN);
  const requestId = isNaN(idFromRef) ? idFromRaw : idFromRef;

  if (!requestId || isNaN(requestId)) {
    res.status(400).json({ success: false, error: "Cannot determine LIS requestId — this movement may not support undo." });
    return;
  }

  // ── Token retrieval ─────────────────────────────────────────────────────
  const [creds] = await db.select().from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));

  if (isLisSandboxMode()) {
    await db.update(livestockMovementsTable).set({ lisSource: "undone" }).where(eq(livestockMovementsTable.id, movId));
    res.json({ success: true, sandbox: true });
    return;
  }

  if (!creds?.isConfigured) { res.status(400).json({ success: false, error: "LIS not configured." }); return; }

  let accessToken = creds.accessToken ?? undefined;
  if (!accessToken || (creds.tokenExpiresAt && new Date(creds.tokenExpiresAt) < new Date(Date.now() + 60_000))) {
    if (creds.refreshToken) {
      const r = await refreshLisToken(creds.refreshToken);
      if (r.success && r.accessToken) {
        accessToken = r.accessToken;
        await db.update(lisFarmTokensTable).set({ accessToken, refreshToken: r.refreshToken ?? undefined, tokenExpiresAt: r.expiresIn ? new Date(Date.now() + r.expiresIn * 1000) : undefined, updatedAt: new Date() }).where(eq(lisFarmTokensTable.farmId, farmId));
      }
    }
    if (!accessToken && creds.lisPasswordEncrypted) {
      const pw = decryptCredential(creds.lisPasswordEncrypted);
      const t = await fetchLisToken(creds.lisUsername!, pw);
      if (t.success && t.accessToken) {
        accessToken = t.accessToken;
        await db.update(lisFarmTokensTable).set({ accessToken, refreshToken: t.refreshToken ?? undefined, tokenExpiresAt: t.expiresIn ? new Date(Date.now() + t.expiresIn * 1000) : undefined, updatedAt: new Date() }).where(eq(lisFarmTokensTable.farmId, farmId));
      }
    }
  }
  if (!accessToken) { res.status(401).json({ success: false, error: "LIS token expired — please reconnect." }); return; }

  const result = await undoLisRequest(accessToken, requestId);

  if (result.ok) {
    await db.update(livestockMovementsTable).set({ lisSource: "undone" }).where(eq(livestockMovementsTable.id, movId));
  }

  res.json({ success: result.ok, sandbox: false, error: result.errorMessage });
});

// ─── LIS OAuth Authorization Code Flow ────────────────────────────────────

/**
 * Resolve the redirect URI for the LIS CLA OAuth callback.
 * Uses LIS_CLA_REDIRECT_URI env var if set, otherwise constructs from request.
 */
function getLisClaCbUrl(req: Request): string {
  const configured = process.env.LIS_CLA_REDIRECT_URI;
  if (configured) return configured;
  const proto = (req.headers["x-forwarded-proto"] as string | undefined) ?? "https";
  const host = (req.headers["x-forwarded-host"] as string | undefined) ?? (req.headers["host"] as string | undefined) ?? "localhost";
  return `${proto}://${host}/api/lis/callback`;
}

/**
 * Sign an OAuth state parameter using HMAC-SHA256 so the callback can verify it
 * without a DB round-trip.  This means both dev and production API servers can
 * verify a state that was issued by either one, as long as they share the same
 * CREDENTIAL_ENCRYPTION_KEY secret.
 *
 * Format:  <hmacHex>.<timestamp>|<farmId>|<base64url(returnUrl)>
 * Expires: 1 hour
 */
function signLisOAuthState(farmId: number, returnUrl: string): string {
  const timestamp = Date.now().toString();
  const payload = `${timestamp}|${farmId}|${Buffer.from(returnUrl).toString("base64url")}`;
  const secret = process.env.CREDENTIAL_ENCRYPTION_KEY ?? "lis-oauth-hmac-fallback";
  const sig = createHmac("sha256", secret).update(payload).digest("hex");
  return `${sig}.${payload}`;
}

function verifyLisOAuthState(state: string): { valid: false } | { valid: true; farmId: number; returnUrl: string } {
  const dotIdx = state.indexOf(".");
  if (dotIdx === -1) return { valid: false };
  const sig = state.slice(0, dotIdx);
  const payload = state.slice(dotIdx + 1);
  const secret = process.env.CREDENTIAL_ENCRYPTION_KEY ?? "lis-oauth-hmac-fallback";
  const expected = createHmac("sha256", secret).update(payload).digest("hex");
  // Use constant-time comparison to prevent timing attacks
  const sigBuf = Buffer.from(sig, "hex");
  const expBuf = Buffer.from(expected, "hex");
  if (sigBuf.length !== expBuf.length || !timingSafeEqual(sigBuf, expBuf)) return { valid: false };
  const parts = payload.split("|");
  if (parts.length < 3) return { valid: false };
  const [timestamp, farmIdStr, returnUrlB64] = parts;
  if (Date.now() - parseInt(timestamp) > 60 * 60 * 1000) return { valid: false }; // 1-hour expiry
  const farmId = parseInt(farmIdStr);
  if (!farmId || isNaN(farmId)) return { valid: false };
  let returnUrl = "https://bdefarmtrac.co.uk/dashboard/farm-settings";
  try { returnUrl = Buffer.from(returnUrlB64, "base64url").toString(); } catch { /* keep default */ }
  return { valid: true, farmId, returnUrl };
}

/**
 * GET /api/lis/authorize?farmId=X&returnUrl=/dashboard/farm-settings
 * Starts the LIS CLA OAuth authorization code flow.
 * Generates a CSRF nonce, stores it, then redirects the farmer to the LIS B2C login page.
 * The redirect_uri (LIS_CLA_REDIRECT_URI) must be registered with LIS in their app registration.
 */
router.get("/lis/authorize", requireAuth, async (req: Request, res: Response): Promise<void> => {
  const farmId = parseInt(req.query["farmId"] as string);
  if (!farmId || isNaN(farmId)) {
    res.status(400).send("Missing or invalid farmId");
    return;
  }
  const returnUrl = (req.query["returnUrl"] as string | undefined) ?? "/dashboard/farm-settings";

  // Build an HMAC-signed state — no DB write needed, works across dev & prod.
  const state = signLisOAuthState(farmId, returnUrl);

  // Ensure a token row exists for this farm (needed later to store access_token etc.)
  const [existing] = await db.select({ id: lisFarmTokensTable.id }).from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));
  if (!existing) {
    await db.insert(lisFarmTokensTable).values({ farmId, isConfigured: false, sandboxMode: isLisSandboxMode() });
  }

  const redirectUri = getLisClaCbUrl(req);
  const authUrl = buildLisAuthUrl(state, redirectUri);

  // SPA clients send Accept: application/json — return the URL so they can
  // navigate to it client-side (preserving the Clerk auth header for this fetch).
  if (req.headers["accept"]?.includes("application/json")) {
    res.json({ url: authUrl });
  } else {
    res.redirect(authUrl);
  }
});

/**
 * GET /api/lis/callback?code=X&state=Y
 * OAuth callback — LIS B2C redirects here after the farmer signs in.
 * Validates state nonce, exchanges code for tokens, stores them, then
 * redirects back to the dashboard with ?lis_connected=true (or ?lis_error=...).
 * Does NOT require authentication middleware — the user is returning from LIS.
 */
router.get("/lis/callback", async (req: Request, res: Response): Promise<void> => {
  const { code, state, error, error_description } = req.query as Record<string, string>;

  // Verify HMAC-signed state — works across dev & prod without a DB lookup.
  const verified = state ? verifyLisOAuthState(state) : { valid: false as const };
  const returnUrl = verified.valid ? verified.returnUrl : "https://bdefarmtrac.co.uk/dashboard/farm-settings";

  const bail = (msg: string) => {
    res.redirect(`${returnUrl}?lis_error=${encodeURIComponent(msg)}`);
  };

  if (error || !code || !state) {
    bail(error_description ?? error ?? "LIS authentication was cancelled or failed. Please try again.");
    return;
  }

  if (!verified.valid) {
    bail("Sign-in link has expired or is invalid. Please try again.");
    return;
  }

  const { farmId } = verified;

  // Exchange code for tokens
  const redirectUri = getLisClaCbUrl(req);
  const tokenResult = await exchangeLisCode(code, redirectUri);

  if (!tokenResult.success || !tokenResult.accessToken) {
    bail(tokenResult.errorMessage ?? "Token exchange with LIS B2C failed. Please try again.");
    return;
  }

  // Store tokens and mark as connected (upsert — row may or may not exist if
  // the authorize was issued by the dev server but callback hits production)
  const [existing] = await db.select({ id: lisFarmTokensTable.id }).from(lisFarmTokensTable).where(eq(lisFarmTokensTable.farmId, farmId));
  const tokenFields = {
    accessToken: tokenResult.accessToken,
    refreshToken: tokenResult.refreshToken ?? undefined,
    tokenExpiresAt: tokenResult.expiresIn ? new Date(Date.now() + tokenResult.expiresIn * 1000) : undefined,
    isConfigured: true,
    sandboxMode: isLisSandboxMode(),
    testStatus: "ok" as const,
    testMessage: tokenResult.sandbox ? "Connected via LIS sign-in (sandbox)" : "Connected via LIS sign-in",
    lastTestedAt: new Date(),
    updatedAt: new Date(),
  };
  if (existing) {
    await db.update(lisFarmTokensTable).set(tokenFields).where(eq(lisFarmTokensTable.farmId, farmId));
  } else {
    await db.insert(lisFarmTokensTable).values({ farmId, ...tokenFields });
  }

  res.redirect(`${returnUrl}?lis_connected=true`);
});

