// ─── Staff Location Pings ─────────────────────────────────────────────────────

router.post("/farms/:farmId/staff-location-ping", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = Number(req.params.farmId);
  const userId = (req as any).auth?.userId;
  if (!userId) { res.status(401).json({ error: "Unauthenticated" }); return; }
  const { userName, latitude, longitude, accuracyM, isSharing, shiftStartedAt } = req.body;
  try {
    if (isSharing && (latitude == null || longitude == null)) {
      res.status(400).json({ error: "latitude and longitude required when isSharing is true" }); return;
    }
    await db.execute(sql`
      INSERT INTO staff_location_pings (farm_id, user_id, user_name, latitude, longitude, accuracy_m, is_sharing, shift_started_at, last_seen_at)
      VALUES (
        ${farmId}, ${userId}, ${String(userName || "Unknown")},
        ${isSharing ? String(latitude) : "0"}, ${isSharing ? String(longitude) : "0"},
        ${accuracyM != null ? String(accuracyM) : null},
        ${Boolean(isSharing)},
        ${shiftStartedAt ? new Date(shiftStartedAt) : null},
        now()
      )
      ON CONFLICT (farm_id, user_id) DO UPDATE SET
        user_name       = EXCLUDED.user_name,
        latitude        = CASE WHEN EXCLUDED.is_sharing THEN EXCLUDED.latitude ELSE staff_location_pings.latitude END,
        longitude       = CASE WHEN EXCLUDED.is_sharing THEN EXCLUDED.longitude ELSE staff_location_pings.longitude END,
        accuracy_m      = CASE WHEN EXCLUDED.is_sharing THEN EXCLUDED.accuracy_m ELSE staff_location_pings.accuracy_m END,
        is_sharing      = EXCLUDED.is_sharing,
        shift_started_at = CASE WHEN EXCLUDED.is_sharing AND EXCLUDED.shift_started_at IS NOT NULL THEN EXCLUDED.shift_started_at ELSE staff_location_pings.shift_started_at END,
        last_seen_at    = now()
    `);
    res.json({ ok: true });
  } catch (err) {
    console.error("[STAFF-LOC PING POST]", err);
    res.status(500).json({ error: "Failed to record location ping" });
  }
});

router.get("/farms/:farmId/staff-locations/live", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = Number(req.params.farmId);
  try {
    const rows = await db.execute(sql`
      SELECT
        user_id        AS "userId",
        user_name      AS "userName",
        latitude,
        longitude,
        accuracy_m     AS "accuracyM",
        is_sharing     AS "isSharing",
        shift_started_at AS "shiftStartedAt",
        last_seen_at   AS "lastSeenAt"
      FROM staff_location_pings
      WHERE farm_id = ${farmId}
        AND is_sharing = true
        AND last_seen_at > now() - interval '2 hours'
      ORDER BY user_name
    `);
    res.json({ pings: rows.rows });
  } catch (err) {
    console.error("[STAFF-LOC GET LIVE]", err);
    res.status(500).json({ error: "Failed to fetch live staff locations" });
  }
});

// ─── GPS Integrations ─────────────────────────────────────────────────────────

const GPS_PROVIDERS = ["teltonika", "samsara", "webfleet", "john_deere", "agco"] as const;
type GpsProvider = typeof GPS_PROVIDERS[number];

router.get("/farms/:farmId/gps-integrations", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = Number(req.params.farmId);
  try {
    const rows = await db.execute<{
      id: number; farm_id: number; provider: string; status: string;
      api_key_encrypted: string | null; webhook_secret_encrypted: string | null;
      access_token_encrypted: string | null; refresh_token_encrypted: string | null;
      token_expires_at: string | null;
      last_sync_at: string | null; last_error: string | null; display_name: string | null;
      created_at: string; updated_at: string;
    }>(
      sql`SELECT * FROM gps_integrations WHERE farm_id = ${farmId} ORDER BY provider`
    );
    const integrations = rows.rows.map(r => ({
      ...r,
      apiKeySet: !!r.api_key_encrypted,
      webhookSecretSet: !!r.webhook_secret_encrypted,
      accessTokenSet: !!r.access_token_encrypted,
      tokenExpiresAt: r.token_expires_at ?? null,
      api_key_encrypted: undefined,
      webhook_secret_encrypted: undefined,
      access_token_encrypted: undefined,
      refresh_token_encrypted: undefined,
    }));
    res.json({ integrations });
  } catch (err) {
    console.error("[GPS] GET integrations:", err);
    res.status(500).json({ error: "Failed to fetch GPS integrations" });
  }
});

router.put("/farms/:farmId/gps-integrations/:provider", requireAuth, requireTenant, async (req: Request, res: Response): Promise<void> => {
  const farmId = Number(req.params.farmId);
  const provider = req.params.provider as GpsProvider;
  if (!(GPS_PROVIDERS as readonly string[]).includes(provider)) {
    res.status(400).json({ error: "Invalid provider" });
    return;
  }
  const { apiKey, webhookSecret, displayName } = req.body as { apiKey?: string; webhookSecret?: string; displayName?: string };
  try {
    const [existing] = await db.select({ id: gpsIntegrationsTable.id, apiKeyEncrypted: gpsIntegrationsTable.apiKeyEncrypted, webhookSecretEncrypted: gpsIntegrationsTable.webhookSecretEncrypted })
      .from(gpsIntegrationsTable)
      .where(and(eq(gpsIntegrationsTable.farmId, farmId), eq(gpsIntegrationsTable.provider, provider)));

    const apiKeyEncrypted = apiKey !== undefined
      ? (apiKey ? encryptCredential(apiKey) : null)
      : (existing?.apiKeyEncrypted ?? null);
    const webhookSecretEncrypted = webhookSecret !== undefined
      ? (webhookSecret ? encryptCredential(webhookSecret) : null)
      : (existing?.webhookSecretEncrypted ?? null);

    const hasCredential = !!(apiKeyEncrypted || webhookSecretEncrypted);
    const status = hasCredential ? "connected" : "disconnected";

    if (existing) {
      await db.update(gpsIntegrationsTable).set({
        apiKeyEncrypted, webhookSecretEncrypted, status,
        displayName: displayName ?? null,
        updatedAt: new Date(),
      }).where(eq(gpsIntegrationsTable.id, existing.id));
    } else {
      await db.insert(gpsIntegrationsTable).values({
        farmId, provider, status, apiKeyEncrypted, webhookSecretEncrypted,
        displayName: displayName ?? null,
      });
    }
    res.json({ success: true });
  } catch (err) {
    console.error("[GPS] PUT integration:", err);
    res.status(500).json({ error: "Failed to save GPS integration" });
  }
});

